import React, { useCallback, useEffect, useState } from "react";
import Header from "../../components/layout/header";
import RackDetail from "../../components/management/rack-detail";
import search_icon from "../../assets/icon/search_icon.svg";

function RackManagement() {
  // API Base URL 상태 관리
  const [baseUrl, setBaseUrl] = useState("");

  const [rackData, setRackData] = useState([]);
  const [searchInput, setSearchInput] = useState(""); // 검색어 입력값
  const [searchTerm, setSearchTerm] = useState(""); // 검색어 적용값
  const [zoneList, setZoneList] = useState([]); // 랙 구역 목록

  // 체크박스로 선택된 자재 ID 목록
  const [selectedRackIds, setSelectedRackIds] = useState([]);

  // 오른쪽 상세 영역에 표시할 선택된 랙 정보
  const [selectedRack, setSelectedRack] = useState(null);

  /*
   * 1. 컴포넌트 마운트 시 public/config.json 로드
   */
  useEffect(() => {
    const loadConfig = async () => {
      try {
        if (window.APP_CONFIG?.apiBaseUrl) {
          setBaseUrl(window.APP_CONFIG.apiBaseUrl);
          return;
        }

        const response = await fetch("/config.json");
        if (!response.ok) {
          throw new Error("config.json 로드 실패");
        }
        const config = await response.json();
        if (config?.apiBaseUrl) {
          setBaseUrl(config.apiBaseUrl);
        } else {
          console.error("config.json에 apiBaseUrl이 정의되어 있지 않습니다.");
        }
      } catch (error) {
        console.error("환경 설정 파일 로드 실패:", error);
      }
    };

    loadConfig();
  }, []);

  /*
   * 랙 목록 조회
   */
  const fetchRackList = useCallback(async (apiBase) => {
    if (!apiBase) return;

    try {
      const response = await fetch(`${apiBase}/get/all/rack/master`, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.detail ||
            result?.msg ||
            `랙 목록 조회 실패: ${response.status}`,
        );
      }

      const list = Array.isArray(result?.data)
        ? result.data
        : Array.isArray(result)
          ? result
          : [];

      // 비활성화된 랙은 목록에서 제외
      const activeRackList = list.filter(
        (item) => item.enable_yn === true || item.enable_yn === 1,
      );

      setRackData(activeRackList);
    } catch (error) {
      console.error("랙 목록 조회 실패:", error);
      setRackData([]);
    }
  }, []);

  /*
   * 존 목록 조회
   */
  const fetchZoneList = useCallback(async (apiBase) => {
    if (!apiBase) return;

    try {
      const response = await fetch(`${apiBase}/get/zone/list`, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result?.detail || result?.msg || "존 목록 조회 실패");
      }

      const list = Array.isArray(result?.data)
        ? result.data
        : Array.isArray(result)
          ? result
          : [];

      setZoneList(list);
    } catch (error) {
      console.error("존 목록 조회 실패:", error);
      setZoneList([]);
    }
  }, []);

  // baseUrl 확보 시 랙 목록 및 존 목록 조회
  useEffect(() => {
    if (baseUrl) {
      fetchRackList(baseUrl);
      fetchZoneList(baseUrl);
    }
  }, [baseUrl, fetchRackList, fetchZoneList]);

  const filteredData = rackData.filter((item) => {
    const keyword = searchTerm.trim().toLowerCase();

    if (!keyword) {
      return true;
    }

    return (
      // 랙 코드
      String(item.rack_code ?? "")
        .toLowerCase()
        .includes(keyword) ||
      // 자재 코드
      String(item.item_code ?? "")
        .toLowerCase()
        .includes(keyword) ||
      // 생성일
      String(item.created_date ?? "")
        .toLowerCase()
        .includes(keyword) ||
      // 수정일
      String(item.updated_date ?? "")
        .toLowerCase()
        .includes(keyword)
    );
  });

  // 전체 선택 여부 확인
  const isAllSelected =
    filteredData.length > 0 &&
    filteredData.every((item) => selectedRackIds.includes(item.seq));

  // 검색 버튼 클릭 시 검색어 적용
  const handleSearch = () => {
    setSearchTerm(searchInput);
  };

  // 검색어 입력 후 Enter 키를 눌렀을 때 검색 적용
  const handleSearchKeyDown = (event) => {
    if (event.key === "Enter") {
      handleSearch();
    }
  };

  // 행을 클릭하면 오른쪽 상세정보에 표시
  const handleShowRackDetail = (item) => {
    if (!item) return;

    setSelectedRack({
      seq: item.seq,
      rack_code: item.rack_code ?? "",
      rack_name: item.rack_name ?? "",
      zone_seq: item.zone_seq ?? item.zone_id ?? item.rack_zone_seq ?? "",
      zone_name: item.zone_name ?? item.rack_zone ?? "",
      rows: item.rows ?? "",
      cols: item.cols ?? "",
      enable_yn: item.enable_yn,
      created_date: item.created_date,
      updated_date: item.updated_date,
      isNew: item.isNew === true,
    });
  };

  // 체크박스 선택 및 해제
  const handleSelectRack = (item) => {
    setSelectedRackIds((currentIds) => {
      const isSelected = currentIds.includes(item.seq);

      if (isSelected) {
        return currentIds.filter((seq) => seq !== item.seq);
      }

      return [...currentIds, item.seq];
    });
  };

  // 선택 삭제 (비활성화)
  const disableRack = async (seq) => {
    if (!baseUrl) return;

    const response = await fetch(`${baseUrl}/disable/rack/master`, {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        seq: Number(seq),
      }),
    });

    const result = await response.json().catch(() => null);

    if (!response.ok) {
      throw new Error(
        result?.detail || result?.msg || `삭제 실패 (${response.status})`,
      );
    }

    if (result?.success === false) {
      throw new Error(result.msg || "삭제 실패");
    }

    return result;
  };

  const handleDeleteSelected = async () => {
    if (selectedRackIds.length === 0) return;

    if (!window.confirm("선택한 랙을 삭제하시겠습니까?")) {
      return;
    }

    try {
      const deletedSeqs = [...selectedRackIds];

      await Promise.all(deletedSeqs.map((seq) => disableRack(seq)));

      // 삭제된 항목을 화면에서 즉시 제거
      setRackData((currentData) =>
        currentData.filter((item) => !deletedSeqs.includes(item.seq)),
      );

      // 삭제한 랙의 상세정보가 열려 있으면 초기화
      if (selectedRack && deletedSeqs.includes(selectedRack.seq)) {
        setSelectedRack(null);
      }

      setSelectedRackIds([]);

      // 서버의 최신 목록 재조회
      await fetchRackList(baseUrl);

      alert("삭제되었습니다.");
    } catch (error) {
      console.error("삭제 실패:", error);
      alert(error.message || "삭제 중 오류가 발생했습니다.");
    }
  };

  const handleAddRack = () => {
    const defaultZone = zoneList[0];

    const newRack = {
      seq: `new-${Date.now()}`,
      rack_code: "-",
      rack_name: "-",
      zone_seq: defaultZone?.seq ?? "",
      zone_name: defaultZone?.zone_name ?? "",
      rows: "",
      cols: "",
      enable_yn: true,
      isNew: true,
    };

    setRackData((currentData) => [newRack, ...currentData]);
    setSelectedRack(newRack);
  };

  // 랙 등록 및 수정
  const handleSaveRack = async (savedRack) => {
    if (!baseUrl) return;

    const isCreateMode = savedRack.isNew === true;

    const payload = isCreateMode
      ? {
          rack_code: String(savedRack.rack_code ?? "").trim(),
          rack_name: String(savedRack.rack_name ?? "").trim(),
          zone_seq: Number(savedRack.zone_seq),
          rows: Number(savedRack.rows),
          cols: Number(savedRack.cols),
        }
      : {
          seq: Number(savedRack.seq),
          rack_code: String(savedRack.rack_code ?? "").trim(),
          rack_name: String(savedRack.rack_name ?? "").trim(),
          zone_seq: Number(savedRack.zone_seq),
          rows: Number(savedRack.rows),
          cols: Number(savedRack.cols),
          enable_yn: Boolean(savedRack.enable_yn),
        };

    if (!payload.rack_code || !payload.rack_name) {
      alert("랙 코드와 랙 이름을 입력해 주세요.");
      return;
    }

    if (!String(savedRack.zone_name ?? "").trim()) {
      alert("랙 구역을 입력해 주세요.");
      return;
    }

    if (!Number.isInteger(payload.zone_seq)) {
      alert(`zone_seq가 없습니다. 현재 값: ${String(savedRack.zone_seq)}`);
      return;
    }

    if (
      !Number.isInteger(payload.rows) ||
      payload.rows < 1 ||
      !Number.isInteger(payload.cols) ||
      payload.cols < 1
    ) {
      alert("가로와 세로는 1 이상의 정수로 입력해 주세요.");
      return;
    }

    const apiUrl = isCreateMode
      ? `${baseUrl}/insert/rack/master`
      : `${baseUrl}/update/rack/master`;

    try {
      const response = await fetch(apiUrl, {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        const errorMessage = Array.isArray(result?.detail)
          ? result.detail
              .map((item) => item.msg)
              .filter(Boolean)
              .join("\n")
          : result?.detail || result?.msg;

        throw new Error(
          errorMessage ||
            `랙 ${isCreateMode ? "등록" : "수정"} 실패: ${response.status}`,
        );
      }

      if (result?.success === false) {
        throw new Error(
          result.msg || `랙 ${isCreateMode ? "등록" : "수정"}에 실패했습니다.`,
        );
      }

      alert(
        result?.msg ||
          `랙이 정상적으로 ${isCreateMode ? "등록" : "수정"}되었습니다.`,
      );

      // 목록을 서버 데이터로 다시 조회
      await fetchRackList(baseUrl);

      if (isCreateMode) {
        setSelectedRack(null);
      } else {
        setSelectedRack({
          ...savedRack,
          seq: payload.seq,
          rack_code: payload.rack_code,
          rack_name: payload.rack_name,
          zone_seq: payload.zone_seq,
          rows: payload.rows,
          cols: payload.cols,
          enable_yn: payload.enable_yn,
          isNew: false,
        });
      }
    } catch (error) {
      console.error(`랙 ${isCreateMode ? "등록" : "수정"} 실패:`, error);

      alert(
        error.message ||
          `랙 ${isCreateMode ? "등록" : "수정"} 중 오류가 발생했습니다.`,
      );
    }
  };
  return (
    <div className="flex h-full w-full items-center justify-center">
      <div className="flex h-[1080px] w-[1560px] flex-col gap-[30px] p-[30px]">
        {/* 헤더 영역 */}
        <div className="flex h-[100px] w-[1500px] shrink-0 items-end gap-[30px]">
          <Header category="관리" title="랙 관리" />
        </div>

        {/* 하단 영역 */}
        <div className="flex h-[890px] w-[1500px] flex-col gap-[30px]">
          {/* 검색 및 버튼 영역 */}
          <div className="flex h-[70px] w-full shrink-0 gap-[20px]">
            <div className="flex h-[70px] min-w-0 flex-1 items-center rounded-[10px] bg-[#EBEDF1] px-[20px]">
              <input
                type="text"
                value={searchInput}
                onChange={(event) => setSearchInput(event.target.value)}
                onKeyDown={handleSearchKeyDown}
                placeholder="검색 (랙 코드, 자재 코드, 날짜)"
                className="h-full w-full bg-transparent text-[24px] font-medium text-[#202020] outline-none placeholder:text-[#A8ADB5]"
              />
              <img
                src={search_icon}
                alt="search"
                className="h-[38px] w-[37px]"
              />
            </div>
            <button
              type="button"
              onClick={handleAddRack}
              className="flex h-[70px] w-[150px] shrink-0 items-center justify-center rounded-[10px] bg-[#243659]"
            >
              <span className="text-[24px] font-semibold text-white">
                신규등록
              </span>
            </button>
            <button
              type="button"
              onClick={handleDeleteSelected}
              disabled={selectedRackIds.length === 0}
              className={`flex h-[70px] w-[150px] shrink-0 items-center justify-center rounded-[10px] ${
                selectedRackIds.length > 0
                  ? "bg-[#D12727]"
                  : "cursor-not-allowed bg-[#EBEDF1]"
              }`}
            >
              <span className="text-[24px] font-semibold text-white">
                선택 삭제
              </span>
            </button>
          </div>

          {/* 구분선 */}
          <div className="h-[2px] w-full shrink-0 bg-[#EEEEEE]" />

          {/* 하단 콘텐츠 영역 */}
          <div className="flex h-[730px] w-[1500px] gap-[30px]">
            {/* 좌측 리스트 영역 */}
            <div className="flex h-[730px] w-[835px] shrink-0 flex-col overflow-hidden rounded-[10px] border border-[#E8E8E8]">
              {/* 리스트 헤더 */}
              <div className="grid h-[60px] w-full shrink-0 grid-cols-[95px_130px_130px_220px_130px_130px] items-center bg-[#243659]">
                <div className="flex items-center justify-center text-center text-[22px] font-bold text-white">
                  선택
                </div>

                <div className="text-center text-[22px] font-bold text-white">
                  랙 코드
                </div>

                <div className="text-center text-[22px] font-bold text-white">
                  랙 이름
                </div>

                <div className="text-center text-[22px] font-bold text-white">
                  구역 정보
                </div>

                <div className="text-center text-[22px] font-bold text-white">
                  랙 규격
                </div>

                <div className="text-center text-[22px] font-bold text-white">
                  상태
                </div>
              </div>

              {/* 리스트 데이터 */}
              <div className="min-h-0 flex-1 overflow-y-auto">
                {filteredData.length === 0 ? (
                  <div className="flex h-full items-center justify-center">
                    <span className="text-[36px] font-bold text-[#8F949E]">
                      목록 없음
                    </span>
                  </div>
                ) : (
                  filteredData.map((item) => {
                    const rackKey = item.isNew
                      ? String(item.seq)
                      : `rack-${item.seq}`;

                    const isChecked = selectedRackIds.includes(item.seq);
                    const isDetailSelected = selectedRack?.seq === item.seq;

                    return (
                      <div
                        key={rackKey}
                        role="button"
                        tabIndex={0}
                        onClick={() => handleShowRackDetail(item)}
                        onKeyDown={(event) => {
                          if (event.key === "Enter" || event.key === " ") {
                            event.preventDefault();
                            handleShowRackDetail(item);
                          }
                        }}
                        className={`grid h-[60px] w-full cursor-pointer grid-cols-[95px_130px_130px_220px_130px_130px] items-center overflow-hidden ${
                          isDetailSelected
                            ? "bg-[#DDE5F3]"
                            : isChecked
                              ? "bg-[#EBEDF1]"
                              : "bg-white"
                        }`}
                      >
                        <div className="flex items-center justify-center overflow-x-hidden">
                          <input
                            type="checkbox"
                            checked={isChecked}
                            onChange={() => handleSelectRack(item)}
                            onClick={(event) => event.stopPropagation()}
                            className="h-[20px] w-[20px] cursor-pointer"
                            aria-label={`${item.rack_code || "랙"} 선택`}
                          />
                        </div>

                        <div className="truncate px-[10px] text-center text-[24px] text-black">
                          {item.rack_code || "-"}
                        </div>

                        <div className="truncate px-[10px] text-center text-[24px] text-black">
                          {item.rack_name || "-"}
                        </div>

                        <div className="truncate px-[10px] text-center text-[24px] text-black">
                          {item.zone_name || "-"}
                        </div>

                        <div className="truncate px-[10px] text-center text-[24px] text-black">
                          {item.cols != null && item.rows != null
                            ? `${item.cols} X ${item.rows}`
                            : "-"}
                        </div>

                        <div className="truncate px-[10px] text-center text-[24px] text-black">
                          {item.enable_yn === true || item.enable_yn === 1
                            ? "사용 가능"
                            : item.enable_yn === false || item.enable_yn === 2
                              ? "미사용"
                              : "-"}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>

            {/* 오른쪽 자재 상세정보 */}
            <div className="flex h-[730px] w-[635px] flex-1 rounded-[10px] bg-[#EBEDF1]">
              <RackDetail
                selectedRack={selectedRack}
                onSaveRack={handleSaveRack}
                zoneList={zoneList}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default RackManagement;
