import { useEffect, useRef, useState } from "react";
import Header from "../../components/layout/header";
import more_icon from "../../assets/icon/more_icon.svg";
import x_icon from "../../assets/icon/x_Icon.svg";
import PickingDetailModal from "../../components/modal/picking-detail-modal";

// 피킹 리스트 행 높이
const ROW_HEIGHT = 90;
// 드래그 미리보기 초기 상태
const EMPTY_DRAG_PREVIEW = {
  visible: false,
  x: 0,
  y: 0,
  width: 0,
  item: null,
};
// 발행확정 모달 초기 상태
const EMPTY_PICKING_MODAL = {
  isOpen: false,
  type: null,
  data: null,
};

function PickingList() {
  // API Base URL 상태 관리
  const [baseUrl, setBaseUrl] = useState("");

  const [processData, setProcessData] = useState([]); // 피킹 리스트 전체 데이터
  const [selectedItemIds, setSelectedItemIds] = useState([]); // 체크된 행의 ID 목록
  const [selectedPicking, setSelectedPicking] = useState(null); // 현재 선택된 피킹 리스트 행

  const [draggedItemId, setDraggedItemId] = useState(null); // 드래그 중인 행의 ID
  const [dragOverIndex, setDragOverIndex] = useState(null); // 드래그 중인 행이 놓일 위치의 인덱스
  const [movingItemIds, setMovingItemIds] = useState([]); // 드래그 중인 행과 함께 이동할 행들의 ID 목록
  const [dragPreview, setDragPreview] = useState(EMPTY_DRAG_PREVIEW); // 드래그 커스텀 미리보기 상태

  const [isChanged, setIsChanged] = useState(false); // 순서 변경 여부
  const [isConfirmModalOpen, setIsConfirmModalOpen] = useState(false); // 순서 변경 확인 모달 상태

  // 하위 자재 상세보기 / 발행확정 모달 상태
  const [pickingModal, setPickingModal] = useState(EMPTY_PICKING_MODAL);

  const listRef = useRef(null); // 피킹 리스트 테이블 영역 참조
  const movingItemIdsRef = useRef([]); // 드래그 중인 행과 함께 이동할 행들의 ID 목록 참조
  const dragOverIndexRef = useRef(null); // 드래그 중인 행이 놓일 위치의 인덱스 참조
  const transparentDragImageRef = useRef(null); // 드래그 시 기본 이미지 제거용 투명 캔버스 참조

  /*
   * 1. 컴포넌트 마운트 시 public/config.json 로드
   */
  useEffect(() => {
    const loadConfig = async () => {
      try {
        if (window.APP_CONFIG?.apiBaseUrl) {
          setBaseUrl(window.APP_CONFIG.apiBaseUrl);
          return;
        }

        const response = await fetch("/config.json");
        if (!response.ok) {
          throw new Error("config.json 로드 실패");
        }
        const config = await response.json();
        if (config?.apiBaseUrl) {
          setBaseUrl(config.apiBaseUrl);
        } else {
          console.error("config.json에 apiBaseUrl이 정의되어 있지 않습니다.");
        }
      } catch (error) {
        console.error("환경 설정 파일 로드 실패:", error);
      }
    };

    loadConfig();
  }, []);

  /*
   * 2. baseUrl 확보 시 피킹 리스트 조회
   */
  useEffect(() => {
    if (!baseUrl) return;

    const fetchPickingList = async () => {
      try {
        const response = await fetch(`${baseUrl}/get/all/pick/list`, {
          method: "GET",
          headers: {
            Accept: "application/json",
          },
        });

        if (!response.ok) {
          throw new Error(`피킹 리스트 조회 실패: ${response.status}`);
        }

        const result = await response.json();

        if (!result.success) {
          throw new Error(result.msg || "피킹 리스트 조회에 실패했습니다.");
        }

        const normalizedData = (result.data ?? []).map((item) => ({
          ...item,
          id: item.seq,
          remarks: item.remarks ?? "",

          // Y, true, 1 모두 발행된 상태로 변환
          publish_yn:
            item.publish_yn === "Y" ||
            item.publish_yn === true ||
            item.publish_yn === 1
              ? "Y"
              : "N",
        }));

        setProcessData(normalizedData);
      } catch (error) {
        console.error("피킹 리스트 전체 조회 오류:", error);
        setProcessData([]);
      }
    };

    fetchPickingList();
  }, [baseUrl]);

  // 기본 드래그 이미지 제거
  useEffect(() => {
    const canvas = document.createElement("canvas");

    canvas.width = 1;
    canvas.height = 1;

    transparentDragImageRef.current = canvas;
  }, []);

  // 드래그 미리보기 위치 갱신
  useEffect(() => {
    if (draggedItemId === null) {
      return undefined;
    }

    const handleWindowDragOver = (event) => {
      if (event.clientX === 0 && event.clientY === 0) {
        return;
      }

      setDragPreview((previous) => {
        if (!previous.visible) {
          return previous;
        }

        return {
          ...previous,
          x: event.clientX,
          y: event.clientY,
        };
      });
    };

    window.addEventListener("dragover", handleWindowDragOver);

    return () => {
      window.removeEventListener("dragover", handleWindowDragOver);
    };
  }, [draggedItemId]);

  const handleRowClick = (item) => {
    setSelectedPicking({ ...item });
  };

  const handleSelectPicking = (itemId) => {
    setSelectedItemIds((previousIds) =>
      previousIds.includes(itemId)
        ? previousIds.filter((id) => id !== itemId)
        : [...previousIds, itemId],
    );
  };

  // 보기 또는 발행확정 모달 열기
  const handleOpenPickingModal = (type, item) => {
    setPickingModal({
      isOpen: true,
      type,
      data: item,
    });
  };

  // 보기 또는 발행확정 모달 닫기
  const handleClosePickingModal = () => {
    setPickingModal(EMPTY_PICKING_MODAL);
  };

  const handleSavePicking = (formData) => {
    const temporarySeq = Date.now();

    const newPickingItem = {
      ...formData,
      seq: temporarySeq,
      id: temporarySeq,

      engine_no: formData.engine_no ?? "",
      mes_seq_no: formData.mes_seq_no ?? "",
      proc_code: formData.proc_code ?? "",
      order_no: formData.order_no ?? "",
      created_at: formData.created_at ?? "",

      remarks: formData.remarks ?? "",
      sub_material_list: [],
      publish_yn: "N",

      isNew: true,

      // 신규등록 행의 확정 버튼 색상 상태
      new_confirmed: false,
    };

    setProcessData((previousData) => [newPickingItem, ...previousData]);

    handleClosePickingModal();
  };

  const handleUpdateSubMaterials = (pickingItemId, subMaterialList) => {
    setProcessData((previousData) =>
      previousData.map((item) =>
        item.id === pickingItemId
          ? {
              ...item,
              sub_material_list: subMaterialList,
            }
          : item,
      ),
    );

    setSelectedPicking((previous) => {
      if (!previous || previous.id !== pickingItemId) {
        return previous;
      }

      return {
        ...previous,
        sub_material_list: subMaterialList,
      };
    });
  };

  // 신규등록 행 확정
  const handleConfirmNewPicking = (itemId) => {
    setProcessData((previousData) =>
      previousData.map((item) =>
        item.id === itemId
          ? {
              ...item,
              new_confirmed: true,
            }
          : item,
      ),
    );

    setSelectedPicking((previous) => {
      if (!previous || previous.id !== itemId) {
        return previous;
      }

      return {
        ...previous,
        new_confirmed: true,
      };
    });
  };

  // 리스트의 발행확정 버튼 클릭
  const handlePublishButtonClick = (item) => {
    if (item.publish_yn === "Y") {
      return;
    }

    handleOpenPickingModal("publish", item);
  };

  // 발행확정
  const handleConfirmPublish = async (item) => {
    try {
      console.log("발행 확정할 피킹 리스트:", item);

      /*
       * if (!baseUrl) return;
       * const response = await fetch(
       *   `${baseUrl}/update/pick/publish`,
       *   {
       *     method: "POST",
       *     headers: {
       *       "Content-Type": "application/json",
       *       Accept: "application/json",
       *     },
       *     body: JSON.stringify({
       *       seq: item.seq,
       *       publish_yn: "Y",
       *     }),
       *   },
       * );
       *
       * if (!response.ok) {
       *   throw new Error(
       *     `발행 확정 실패: ${response.status}`,
       *   );
       * }
       *
       * const result = await response.json();
       *
       * if (!result.success) {
       *   throw new Error(
       *     result.msg ||
       *       "발행 확정에 실패했습니다.",
       *   );
       * }
       */

      // 해당 행만 발행 상태로 변경
      setProcessData((previousData) =>
        previousData.map((processItem) =>
          processItem.id === item.id
            ? {
                ...processItem,
                publish_yn: "Y",
              }
            : processItem,
        ),
      );

      // 현재 선택된 행 정보도 같이 변경
      setSelectedPicking((previous) => {
        if (!previous || previous.id !== item.id) {
          return previous;
        }

        return {
          ...previous,
          publish_yn: "Y",
        };
      });

      // 발행확정 모달 닫기
      handleClosePickingModal();
    } catch (error) {
      console.error("피킹 리스트 발행 확정 오류:", error);
    }
  };

  // 드래그 상태 초기화
  const resetDragState = () => {
    setDraggedItemId(null);
    setDragOverIndex(null);
    setMovingItemIds([]);
    setDragPreview(EMPTY_DRAG_PREVIEW);

    movingItemIdsRef.current = [];
    dragOverIndexRef.current = null;
  };

  // 드래그 시작
  const handleDragStart = (event, itemId) => {
    const draggedItem = processData.find((item) => item.id === itemId);

    if (!draggedItem) {
      event.preventDefault();
      return;
    }

    // 체크된 행은 함께 이동
    const nextMovingItemIds = selectedItemIds.includes(itemId)
      ? processData
          .filter((item) => selectedItemIds.includes(item.id))
          .map((item) => item.id)
      : [itemId];

    movingItemIdsRef.current = nextMovingItemIds;

    setDraggedItemId(itemId);
    setMovingItemIds(nextMovingItemIds);

    const listWidth = listRef.current?.getBoundingClientRect().width ?? 1500;

    setDragPreview({
      visible: true,
      x: event.clientX,
      y: event.clientY,
      width: Math.max(listWidth - 20, 0),
      item: draggedItem,
    });

    event.dataTransfer.effectAllowed = "move";

    event.dataTransfer.setData("text/plain", JSON.stringify(nextMovingItemIds));

    event.dataTransfer.setData(
      "application/json",
      JSON.stringify(nextMovingItemIds),
    );

    if (transparentDragImageRef.current) {
      event.dataTransfer.setDragImage(transparentDragImageRef.current, 0, 0);
    }
  };

  // 드롭 위치 계산
  const handleListDragOver = (event) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";

    const listElement = listRef.current;

    if (!listElement || movingItemIdsRef.current.length === 0) {
      return;
    }

    const visibleRows = Array.from(
      listElement.querySelectorAll('[data-picking-row][data-dragging="false"]'),
    );

    let nextIndex = processData.length;

    for (const row of visibleRows) {
      const rect = row.getBoundingClientRect();
      const middleY = rect.top + rect.height / 2;

      if (event.clientY < middleY) {
        nextIndex = Number(row.dataset.rowIndex);
        break;
      }
    }

    if (dragOverIndexRef.current === nextIndex) {
      return;
    }

    dragOverIndexRef.current = nextIndex;
    setDragOverIndex(nextIndex);
  };

  const handleDrop = (event) => {
    event.preventDefault();
    event.stopPropagation();

    const targetIndex = dragOverIndexRef.current;

    let droppedItemIds = movingItemIdsRef.current;

    try {
      const dragData =
        event.dataTransfer.getData("application/json") ||
        event.dataTransfer.getData("text/plain");

      if (dragData) {
        droppedItemIds = JSON.parse(dragData);
      }
    } catch (error) {
      console.error("드래그 데이터 처리 실패:", error);
    }

    if (
      targetIndex === null ||
      !Array.isArray(droppedItemIds) ||
      droppedItemIds.length === 0
    ) {
      resetDragState();
      return;
    }

    setProcessData((currentData) => {
      const movingItems = currentData.filter((item) =>
        droppedItemIds.includes(item.id),
      );

      const remainingItems = currentData.filter(
        (item) => !droppedItemIds.includes(item.id),
      );

      const removedBeforeTarget = currentData
        .slice(0, targetIndex)
        .filter((item) => droppedItemIds.includes(item.id)).length;

      const adjustedIndex = Math.max(
        0,
        Math.min(targetIndex - removedBeforeTarget, remainingItems.length),
      );

      const nextData = [...remainingItems];

      nextData.splice(adjustedIndex, 0, ...movingItems);

      return nextData;
    });

    setIsChanged(true);
    resetDragState();
  };

  // 드래그 종료 시 상태 초기화
  const handleDragEnd = () => {
    resetDragState();
  };

  // 리스트 분할 버튼 클릭
  const handleSplitList = () => {
    const selectedItems = processData.filter((item) =>
      selectedItemIds.includes(item.id),
    );

    sessionStorage.setItem(
      "selectedPickingList",
      JSON.stringify(selectedItems),
    );

    window.location.href = "/picking-list-partition";
  };

  // 변경 사항 적용 버튼 클릭
  const handleApplyChanges = () => {
    if (isChanged) {
      setIsConfirmModalOpen(true);
    }
  };

  // 순서 변경 확인 모달 적용
  const handleConfirmChanges = () => {
    const reorderedData = processData.map((item, index) => ({
      ...item,
      order: index + 1,
    }));

    console.log("최종 적용할 피킹 리스트 순서:", reorderedData);

    setProcessData(reorderedData);
    setIsChanged(false);
    setIsConfirmModalOpen(false);
  };

  // 순서 변경 확인 모달 취소
  const handleCancelChanges = () => {
    setIsConfirmModalOpen(false);
  };

  const placeholderHeight = Math.max(
    movingItemIds.length * ROW_HEIGHT,
    ROW_HEIGHT,
  );

  // 피킹 리스트 신규등록 모달 열기
  const handleOpenCreateModal = () => {
    handleOpenPickingModal("create", null);
  };

  return (
    <div className="flex h-full w-full items-center justify-center">
      <div className="flex h-[1080px] w-[1560px] flex-col gap-[30px] p-[30px]">
        <div className="flex h-[100px] w-[1500px] shrink-0 items-end gap-[30px]">
          <Header category="관리" title="피킹 리스트 관리" />
        </div>

        <div className="flex h-[890px] w-[1500px] flex-col gap-[30px]">
          <div className="flex h-[70px] w-full shrink-0 justify-end gap-[20px]">
            <button
              type="button"
              onClick={handleSplitList}
              className="flex h-[70px] w-[177px] shrink-0 cursor-pointer items-center justify-center rounded-[10px] bg-[#243659] text-[24px] font-semibold text-white"
            >
              리스트 분할
            </button>

            <button
              type="button"
              onClick={handleOpenCreateModal}
              className="flex h-[70px] w-[150px] shrink-0 cursor-pointer items-center justify-center rounded-[10px] bg-[#243659] px-[20px]"
            >
              <span className="text-[24px] font-semibold text-white">
                신규등록
              </span>
            </button>

            <button
              type="button"
              onClick={handleApplyChanges}
              disabled={!isChanged}
              className={`flex h-[70px] w-[177px] shrink-0 items-center justify-center rounded-[10px] text-[24px] font-semibold text-white ${
                isChanged
                  ? "cursor-pointer bg-[#243659]"
                  : "cursor-not-allowed bg-[#A8ADB5]"
              }`}
            >
              변경 사항 적용
            </button>
          </div>

          <div className="h-[2px] w-full shrink-0 bg-[#EEEEEE]" />

          <div className="flex h-[730px] w-full gap-[30px]">
            <div className="flex h-[730px] w-full shrink-0 flex-col overflow-hidden rounded-[10px] border border-[#E8E8E8]">
              {/* 테이블 헤더 */}
              <div className="grid h-[60px] w-full shrink-0 grid-cols-[95px_220px_150px_150px_257.5px_257.5px_150px_150px_70px] items-center bg-[#243659]">
                <div className="text-center text-[24px] font-bold text-white">
                  선택
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  호기
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  서열
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  공정
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  지시 번호
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  예정일
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  하위 자재
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  발행 확정
                </div>

                <div />
              </div>

              {/* 테이블 데이터 */}
              <div
                ref={listRef}
                onDragOver={handleListDragOver}
                onDrop={handleDrop}
                className="hide-scrollbar min-h-0 flex-1 overflow-y-auto"
              >
                {processData.map((item, index) => {
                  const isDragging = movingItemIds.includes(item.id);

                  const isChecked = selectedItemIds.includes(item.id);

                  const isSelected = selectedPicking?.id === item.id;

                  const isPublished = item.publish_yn === "Y";

                  const isNew = item.isNew === true;

                  const isNewConfirmed = item.new_confirmed === true;

                  return (
                    <div key={item.id}>
                      {/* 드롭 위치 점선 영역 */}
                      {draggedItemId !== null && dragOverIndex === index && (
                        <div
                          className="mx-[15px] rounded-[20px] border-2 border-dashed border-[#C7CBD1] bg-white"
                          style={{
                            height: `${placeholderHeight}px`,
                          }}
                        />
                      )}

                      <div
                        data-picking-row
                        data-row-index={index}
                        data-dragging={isDragging ? "true" : "false"}
                        onClick={() => handleRowClick(item)}
                        className={`grid w-full grid-cols-[95px_220px_150px_150px_257.5px_257.5px_150px_150px_70px] items-center overflow-hidden transition-[height,opacity] duration-150 ${
                          isDragging
                            ? "h-0 opacity-0"
                            : isNew
                              ? "h-[90px] bg-[#E9EBEF] opacity-100"
                              : isSelected || isChecked
                                ? "h-[90px] bg-[#F1F7FF] opacity-100"
                                : "h-[90px] bg-white opacity-100"
                        }`}
                      >
                        {/* 선택 */}
                        <div className="flex items-center justify-center">
                          <input
                            type="checkbox"
                            checked={isChecked}
                            onChange={() => handleSelectPicking(item.id)}
                            onClick={(event) => event.stopPropagation()}
                            className="h-[20px] w-[20px] cursor-pointer focus:ring-0"
                            aria-label={`${item.order_no || "피킹 리스트"} 선택`}
                          />
                        </div>

                        {/* 호기 */}
                        <div className="flex items-center justify-center px-[10px]">
                          {isNew ? (
                            <div className="flex h-[40px] w-[200px] items-center justify-center rounded-[10px] font-normal  bg-white text-[24px] text-black">
                              {item.engine_no || "-"}
                            </div>
                          ) : (
                            <div className="truncate text-center text-[24px] text-black">
                              {item.engine_no || "-"}
                            </div>
                          )}
                        </div>

                        {/* 서열 */}
                        <div className="flex items-center justify-center px-[10px]">
                          {isNew ? (
                            <div className="flex h-[40px] w-[200px] items-center justify-center rounded-[10px] font-normal  bg-white text-[24px] text-black">
                              {item.mes_seq_no || "-"}
                            </div>
                          ) : (
                            <div className="truncate text-center text-[24px] text-black">
                              {item.mes_seq_no || "-"}
                            </div>
                          )}
                        </div>

                        {/* 공정 */}
                        <div className="flex items-center justify-center px-[10px]">
                          {isNew ? (
                            <div className="flex h-[40px] w-[200px] items-center justify-center rounded-[10px] font-normal bg-white text-[24px] text-black">
                              {item.proc_code || "-"}
                            </div>
                          ) : (
                            <div className="truncate text-center text-[24px] text-black">
                              {item.proc_code || "-"}
                            </div>
                          )}
                        </div>

                        {/* 지시 번호 */}
                        <div className="flex items-center justify-center px-[10px]">
                          {isNew ? (
                            <div className="flex h-[40px] w-[200px] items-center justify-center rounded-[10px] font-normal  bg-white text-[24px] text-black">
                              {item.order_no || "-"}
                            </div>
                          ) : (
                            <div className="truncate text-center text-[24px] text-black">
                              {item.order_no || "-"}
                            </div>
                          )}
                        </div>

                        {/* 예정일 */}
                        <div className="flex items-center justify-center px-[10px]">
                          {isNew ? (
                            <div className="flex h-[40px] w-[200px] items-center justify-center rounded-[10px] font-normal  bg-white text-[24px] text-black">
                              {item.created_at || "-"}
                            </div>
                          ) : (
                            <div className="truncate text-center text-[24px] text-black">
                              {item.created_at || "-"}
                            </div>
                          )}
                        </div>

                        {/* 하위 자재 보기 / 추가 */}
                        <div className="flex items-center justify-center">
                          <button
                            type="button"
                            onClick={(event) => {
                              event.stopPropagation();

                              handleOpenPickingModal("detail", item);
                            }}
                            className={`flex h-[50px] w-[110px] items-center justify-center rounded-[10px] px-[20px] text-[24px] font-normal text-white ${
                              isNew ? "bg-[#8F949E]" : "bg-[#9A9FA8]"
                            }`}
                          >
                            {isNew ? "추가" : "보기"}
                          </button>
                        </div>

                        {/* 발행 확정 */}
                        <div className="flex items-center justify-center">
                          <button
                            type="button"
                            // 기존 행이 발행된 경우에만 비활성화
                            disabled={!isNew && isPublished}
                            onClick={(event) => {
                              event.stopPropagation();

                              // 신규 행은 확정 문구 유지 + 배경색만 변경
                              if (isNew) {
                                handleConfirmNewPicking(item.id);
                                return;
                              }

                              // 기존 행이 이미 발행된 경우 실행하지 않음
                              if (isPublished) {
                                return;
                              }

                              // 기존 행은 발행확정 모달 열기
                              handlePublishButtonClick(item);
                            }}
                            className={`flex h-[50px] w-[120px] items-center justify-center rounded-[10px] px-[10px] text-[24px] font-normal text-white ${
                              isNew
                                ? isNewConfirmed
                                  ? "cursor-pointer bg-[#7A8CB0]"
                                  : "cursor-pointer bg-[#243659]"
                                : isPublished
                                  ? "cursor-not-allowed bg-[#7A8CB0]"
                                  : "cursor-pointer bg-[#243659]"
                            }`}
                          >
                            {isNew ? "확정" : isPublished ? "취소" : "확정"}
                          </button>
                        </div>

                        {/* 드래그 핸들 */}
                        <div className="flex items-center justify-center">
                          <div
                            draggable
                            onMouseDown={(event) => event.stopPropagation()}
                            onClick={(event) => event.stopPropagation()}
                            onDragStart={(event) => {
                              event.stopPropagation();

                              handleDragStart(event, item.id);
                            }}
                            onDragEnd={handleDragEnd}
                            className="flex h-[50px] w-[50px] cursor-grab select-none items-center justify-center active:cursor-grabbing"
                          >
                            <img
                              src={more_icon}
                              alt="순서 변경"
                              draggable={false}
                              className="pointer-events-none h-[24px] w-[24px] select-none"
                            />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}

                {/* 리스트 맨 아래 드롭 위치 */}
                {draggedItemId !== null &&
                  dragOverIndex === processData.length && (
                    <div
                      className="mx-[15px] rounded-[20px] border-2 border-dashed border-[#C7CBD1] bg-white"
                      style={{
                        height: `${placeholderHeight}px`,
                      }}
                    />
                  )}

                <div className="h-[30px] w-full" />
              </div>
            </div>
          </div>

          {/* 순서 변경 확인 모달 */}
          {isConfirmModalOpen && (
            <div
              className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/20 backdrop-blur-[6px]"
              onClick={handleCancelChanges}
            >
              <div
                className="flex h-[275px] w-[700px] flex-col gap-[30px] rounded-[20px] bg-white p-[30px]"
                onClick={(event) => event.stopPropagation()}
              >
                <div className="relative mx-auto flex h-[50px] w-[640px] items-center justify-center">
                  <h2 className="text-[40px] font-extrabold text-[#222222]">
                    피킹 리스트 순서 변경
                  </h2>

                  <button
                    type="button"
                    onClick={handleCancelChanges}
                    className="absolute right-0 flex h-[37px] w-[37px] items-center justify-center"
                  >
                    <img
                      src={x_icon}
                      alt="닫기"
                      className="h-[18.5px] w-[18.5px]"
                    />
                  </button>
                </div>

                <div className="flex h-[35px] items-center justify-center">
                  <p className="text-[28px] font-normal text-[#222222]">
                    피킹 리스트 순서를 다음과 같이 변경합니다.
                  </p>
                </div>

                <div className="flex h-[70px] w-full gap-[30px]">
                  <button
                    type="button"
                    onClick={handleCancelChanges}
                    className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#8F949E] text-[32px] font-extrabold text-white"
                  >
                    변경 취소
                  </button>

                  <button
                    type="button"
                    onClick={handleConfirmChanges}
                    className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#243659] text-[32px] font-extrabold text-white"
                  >
                    변경 확인
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* 드래그 커스텀 미리보기 */}
          {dragPreview.visible && dragPreview.item && (
            <div
              className="pointer-events-none fixed z-[10000] grid h-[90px] grid-cols-[95px_220px_150px_150px_257.5px_257.5px_150px_150px_70px] items-center overflow-hidden rounded-[20px] border border-[#D7DADF] bg-[#F1F2F4] shadow-[0_5px_16px_rgba(0,0,0,0.22)]"
              style={{
                left: `${dragPreview.x}px`,
                top: `${dragPreview.y}px`,
                width: `${dragPreview.width}px`,
                transform: "translate(calc(-100% + 55px), -50%)",
              }}
            >
              <div className="flex items-center justify-center">
                <input
                  type="checkbox"
                  checked={selectedItemIds.includes(dragPreview.item.id)}
                  readOnly
                  tabIndex={-1}
                  className="pointer-events-none h-[20px] w-[20px]"
                />
              </div>

              <div className="truncate px-[10px] text-center text-[24px] text-black">
                {dragPreview.item.engine_no || "-"} {/* 호기 */}
              </div>

              <div className="truncate px-[10px] text-center text-[24px] text-black">
                {dragPreview.item.mes_seq_no || "-"} {/* 서열 */ }
              </div>

              <div className="truncate px-[10px] text-center text-[24px] text-black">
                {dragPreview.item.proc_code || "-"} {/* 공정 */ }
              </div>

              <div className="truncate px-[10px] text-center text-[24px] text-black">
                {dragPreview.item.order_no || "-"} {/* 지시 번호 */ }
              </div>

              <div className="truncate px-[10px] text-center text-[24px] text-black">
                {dragPreview.item.confirmed_at || "-"}  {/* 예정일 */ }
              </div>
              {/* 하위 자재 보기 버튼 */}
              <div className="flex items-center justify-center">
                <div className="flex h-[50px] w-[110px] items-center justify-center rounded-[10px] bg-[#9A9FA8] text-[24px] font-normal text-white">
                  보기
                </div>
              </div>

              {/* 발행 확정 버튼 */}
              <div className="flex items-center justify-center">
                <div
                  className={`flex h-[50px] w-[120px] items-center justify-center rounded-[10px] px-[10px] font-normal text-white ${
                    dragPreview.item.publish_yn === "Y"
                      ? "bg-[#7A8CB0] text-[24px]"
                      : "bg-[#243659] text-[21px]"
                  }`}
                >
                  {dragPreview.item.publish_yn === "Y" ? "취소" : "확정"}
                </div>
              </div>
              {/* 드래그 핸들 */}
              <div className="flex items-center justify-center">
                <img
                  src={more_icon}
                  alt=""
                  draggable={false}
                  className="h-[24px] w-[24px]"
                />
              </div>

              {movingItemIds.length > 1 && (
                <div className="absolute right-[8px] top-[4px] flex h-[28px] min-w-[28px] items-center justify-center rounded-full bg-[#243659] px-[7px] text-[15px] font-bold text-white">
                  {movingItemIds.length}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* 하위 자재 상세보기 / 발행확정 모달 */}
      <PickingDetailModal
        isOpen={pickingModal.isOpen}
        modalType={pickingModal.type}
        data={pickingModal.data ?? {}}
        onClose={handleClosePickingModal}
        onSave={handleSavePicking}
        onUpdateSubMaterials={handleUpdateSubMaterials}
        onConfirmPublish={handleConfirmPublish}
      />
    </div>
  );
}

export default PickingList;
