import x_icon from "../../assets/icon/x_Icon.svg";

function KlpnModal({ data, onClose }) {
  const wLpnDetails = [
    { label: "LPN", value: data?.w_lpn_code ?? "" },
    { label: "적재 위치", value: data?.w_location ?? "-" },
    { label: "호기", value: data?.machine_no ?? "-" },
    { label: "등록일", value: data?.registered_date ?? "-" },
    { label: "생산 서열", value: data?.production_sequence ?? "-" },
  ];

  // D-LPN
  const dLpnDetails = [
    { label: "LPN", value: data?.d_lpn_code ?? "-" },
    { label: "적재 위치", value: data?.d_location ?? "-" },
    { label: "호기", value: data?.machine_no ?? "-" },
    { label: "등록일", value: data?.registered_date ?? "-" },
    { label: "생산 서열", value: data?.production_sequence ?? "-" },
  ];

  const Details = [
    { label: "호기", value: data?.machine_no ?? "-" },
    { label: "공정", value: data?.process ?? "-" },
    { label: "서열", value: data?.order ?? "-" },

  ];

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/30 backdrop-blur-[7px]">
      <div className="relative flex min-h-[465px] w-[825px] flex-col items-center gap-[30px] rounded-[20px] bg-white p-[30px]">
        {/* 모달 헤더 */}
        <div className="relative h-[50px] w-full">
          <h2 className="absolute inset-0 flex items-center justify-center whitespace-nowrap text-[40px] font-extrabold">
            {data?.lpn_code ?? "-"}
          </h2>

          <button
            type="button"
            onClick={onClose}
            aria-label="모달 닫기"
            className="absolute right-0 top-1/2 flex h-[37px] w-[37px] -translate-y-1/2 items-center justify-center"
          >
            <img
              src={x_icon}
              alt=""
              aria-hidden="true"
              className="h-[18.5px] w-[18.5px]"
            />
          </button>
        </div>

        {/* 상세 정보 영역 */}
        <div className="flex min-h-[325px] w-[765px] flex-col gap-[10px]">
          <div className="flex h-[25px] w-full justify-end text-[20px] text-[#9A9FA8]">
            발행 일자 : {data?.txn_date?.replace("T", " ").slice(0, 19) ?? "-"}
          </div>

          <div className="flex flex-col min-h-[290px] w-full gap-[15px] rounded-[20px] border border-[#DFDFDF] p-[20px]">
            <div className="flex w-full h-[50px] rounded-[20px] items-center border border-[#DFDFDF]">
              <div className="flex w-full items-center">
                <span className="rounded-l-[20px] h-[50px] w-[150px] bg-[#243659] flex justify-center items-center text-[22px] font-bold text-white">
                  호기
                </span>
                <span className="flex h-[50px] w-full justify-center items-center text-[22px] font-normal text-black">
                  {data?.engine_no ?? "-"}
                </span>
              </div>
              <div className="flex w-full items-center">
                <span className="h-[50px] w-[150px] bg-[#243659] flex justify-center items-center text-[22px] font-bold text-white">
                  공정
                </span>
                <span className="flex h-[50px] w-full justify-center items-center text-[22px] font-normal text-black">
                  {data?.proc_code ?? "-"}
                </span>
              </div>
              <div className="flex w-full items-center ">
                <span className="h-[50px] w-[150px] bg-[#243659] flex justify-center items-center text-[22px] font-bold text-white">
                  서열
                </span>
                <span className="flex h-[50px] w-full justify-center items-center text-[22px] font-normal text-black">
                  {data?.seq ?? "-"}
                </span>
              </div>
            </div>
            {/* LPN 기본 정보 */}
            <div className="flex gap-[10px] overflow-hidden">
              {/* W-LPN */}
              <div className="flex min-h-[250px] w-full flex-col overflow-hidden rounded-[10px] border border-[#D9DDE5]">
                <div className="flex h-[45px] items-center justify-center bg-[#243659] text-[22px] font-bold text-[#E9ECF2]">
                  W-LPN
                </div>

                {wLpnDetails.map((item) => (
                  <div
                    key={item.label}
                    className="grid flex-1 grid-cols-[150px_1fr] border-b border-[#D9DDE5] last:border-b-0"
                  >
                    <div className="flex items-center justify-center bg-[#E9ECF2] text-[22px] font-semibold text-[#243659]">
                      {item.label}
                    </div>

                    <div className="flex items-center justify-center bg-white text-[22px]">
                      {item.value}
                    </div>
                  </div>
                ))}
              </div>

              {/* D-LPN */}
              <div className="flex min-h-[250px] w-full flex-col overflow-hidden rounded-[10px] border border-[#D9DDE5]">
                <div className="flex h-[45px] items-center justify-center bg-[#243659] text-[22px] font-bold text-[#E9ECF2]">
                  D-LPN
                </div>

                {dLpnDetails.map((item, index) => (
                  <div
                    key={`${item.label}-${index}`}
                    className="grid flex-1 grid-cols-[150px_1fr] border-b border-[#D9DDE5] last:border-b-0"
                  >
                    <div className="flex items-center justify-center bg-[#E9ECF2] text-[22px] font-semibold text-[#243659]">
                      {item.label}
                    </div>

                    <div className="flex items-center justify-center bg-white text-[22px]">
                      {item.value}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default KlpnModal;
