import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";

import hd_infracore_logo from "../../assets/icon/hd_infracore_logo.svg";
import arrowUp_icon from "../../assets/icon/arrowUp_icon.svg";
import arrowDown_icon from "../../assets/icon/arrowDown_icon.svg";

import { ReactComponent as DashboardIcon } from "../../assets/icon/dashboard_icon.svg";
import { ReactComponent as RackViewIcon } from "../../assets/icon/rackView_icon.svg";
import { ReactComponent as ViewIcon } from "../../assets/icon/view_icon.svg";
import { ReactComponent as RackIcon } from "../../assets/icon/rack_icon.svg";
import { ReactComponent as ProcessIcon } from "../../assets/icon/process_icon.svg";
import { ReactComponent as MaterialMasterIcon } from "../../assets/icon/material_master_icon.svg";
import { ReactComponent as PickingListIcon } from "../../assets/icon/picking_list_icon.svg";

export default function Sidebar() {
  const navigate = useNavigate();
  const location = useLocation();
// 현재 선택된 메뉴인지 확인
  const isActive = (path) => location.pathname === path;
// 메뉴 열기/닫기 상태
  const [openMenus, setOpenMenus] = useState({
    home: true,
    search: true,
    management: true,
  });
// 메뉴 펼치기/접기
  const toggleMenu = (menuName) => {
    setOpenMenus((prev) => ({
      ...prev,
      [menuName]: !prev[menuName],
    }));
  };
// 메뉴 활성화 여부에 따른 스타일 반환
  const getMenuClass = (path) => {
    return `flex h-[60px] w-[320px] cursor-pointer items-center justify-start gap-[10px] rounded-[10px] px-[20px] py-[10px] font-semibold transition-all ${
      isActive(path)
        ? "bg-[#45BE3F] text-white"
        : "bg-transparent text-[#6487D0] hover:bg-white/10 hover:text-white"
    }`;
  };
// 아이콘 공통 스타일
  const getIconClass = (sizeClass) => {
  return `${sizeClass} shrink-0 fill-current text-current [&_*]:fill-current`;
};
  return (
    <aside className="flex h-[1080px] w-[360px] select-none flex-col gap-[20px] bg-[#243659] px-[20px] py-[70px]">
      {/* 로고 */}
      <div className="flex w-[320px] flex-col items-center justify-center gap-[10px] p-[5px]">
        <img
          src={hd_infracore_logo}
          alt="HD 현대인프라코어"
          className="h-[47.9px] w-[250px]"
        />

        <p className="ml-2 text-[20px] font-bold text-white">
          자재 통합 관리형 WMS
        </p>
      </div>

      {/* 구분선 */}
      <div className="h-[2px] w-[320px] shrink-0 bg-[#356EED]" />

      {/* 메뉴 영역 */}
      <nav className="min-h-[608px] w-[320px] flex-1 space-y-6 overflow-y-auto">
        {/* 홈 메뉴 */}
        <section className="flex flex-col">
          <button
            type="button"
            onClick={() => toggleMenu("home")}
            className="mb-1 flex h-[40px] w-[320px] cursor-pointer items-center justify-start gap-[10px] font-extrabold"
          >
            <img
              src={openMenus.home ? arrowUp_icon : arrowDown_icon}
              alt=""
              className="h-[27px] w-[25px] object-contain"
            />

            <span className="text-[22px] font-extrabold text-white">홈</span>
          </button>

          {openMenus.home && (
            <button
              type="button"
              onClick={() => navigate("/dashboard")}
              className={getMenuClass("/dashboard")}
            >
              <span className="flex h-[50px] w-[50px] shrink-0 items-center justify-center">
                <DashboardIcon
                  className={getIconClass("h-[26.2px] w-[35.54px]")}
                />
              </span>

              <span className="flex items-center text-[22px]">대시보드</span>
            </button>
          )}
        </section>

        {/* 조회 메뉴 */}
        <section className="flex flex-col">
          <button
            type="button"
            onClick={() => toggleMenu("search")}
            className="mb-1 flex h-[40px] w-[320px] cursor-pointer items-center justify-start gap-[10px] font-extrabold"
          >
            <img
              src={openMenus.search ? arrowUp_icon : arrowDown_icon}
              alt=""
              className="h-[27px] w-[25px] object-contain"
            />

            <span className="text-[22px] font-extrabold text-white">조회</span>
          </button>

          {openMenus.search && (
            <div className="flex flex-col gap-1">
              {/* 랙 적재 현황 조회 */}
              <button
                type="button"
                onClick={() => navigate("/rack-view")}
                className={getMenuClass("/rack-view")}
              >
                <span className="flex h-[50px] w-[50px] shrink-0 items-center justify-center">
                  <RackViewIcon
                    className={getIconClass(
                      "/rack-view",
                      "h-[30px] w-[29.07px]",
                    )}
                  />
                </span>

                <span className="flex items-center text-[22px]">
                  랙 적재 현황 조회
                </span>
              </button>

              {/* 이력 조회 */}
              <button
                type="button"
                onClick={() => navigate("/history")}
                className={getMenuClass("/history")}
              >
                <span className="flex h-[50px] w-[50px] shrink-0 items-center justify-center">
                  <ViewIcon
                    className={getIconClass("/history", "h-[30px] w-[30px]")}
                  />
                </span>

                <span className="flex items-center text-[22px]">이력 조회</span>
              </button>
            </div>
          )}
        </section>

        {/* 관리 메뉴 */}
        <section className="flex flex-col">
          <button
            type="button"
            onClick={() => toggleMenu("management")}
            className="mb-1 flex h-[40px] w-[320px] cursor-pointer items-center justify-start gap-[10px] font-extrabold"
          >
            <img
              src={openMenus.management ? arrowUp_icon : arrowDown_icon}
              alt=""
              className="h-[27px] w-[25px] object-contain"
            />

            <span className="text-[22px] font-extrabold text-white">관리</span>
          </button>

          {openMenus.management && (
            <div className="flex flex-col gap-1">
              {/* 랙 관리 */}
              <button
                type="button"
                onClick={() => navigate("/rack-management")}
                className={getMenuClass("/rack-management")}
              >
                <span className="flex h-[50px] w-[50px] shrink-0 items-center justify-center">
                  <RackIcon
                    className={getIconClass(
                      "/rack-management",
                      "h-[30px] w-[23.98px]",
                    )}
                  />
                </span>

                <span className="flex items-center text-[22px]">랙 관리</span>
              </button>

              {/* 공정 순서 관리 */}
              <button
                type="button"
                onClick={() => navigate("/process-management")}
                className={getMenuClass("/process-management")}
              >
                <span className="flex h-[50px] w-[50px] shrink-0 items-center justify-center">
                  <ProcessIcon
                    className={getIconClass(
                      "/process-management",
                      "h-[25.12px] w-[30px]",
                    )}
                  />
                </span>

                <span className="flex items-center text-[22px]">
                  공정 순서 관리
                </span>
              </button>
              {/* 자재 마스터 관리 */}
              <button
                type="button"
                onClick={() => navigate("/material-master")}
                className={getMenuClass("/material-master")}
              >
                <span className="flex h-[50px] w-[50px] shrink-0 items-center justify-center">
                  <MaterialMasterIcon
                    className={`h-[30px] w-[28.27px] shrink-0 ${
                      isActive("/material-master")
                        ? "[&_*]:stroke-white"
                        : "text-[#D8E3FA]"
                    }`}
                  />
                </span>

                <span className="flex items-center text-[22px]">
                  자재 마스터 관리
                </span>
              </button>
              {/* 피킹 리스트 관리 */}
              <button
                type="button"
                onClick={() => navigate("/picking-list")}
                className={getMenuClass("/picking-list")}
              >
                <span className="flex h-[50px] w-[50px] shrink-0 items-center justify-center">
                  <PickingListIcon
                    className={`h-[30px] w-[28.27px] shrink-0 ${
                      isActive("/picking-list")
                        ? "text-white [&_*]:fill-white [&_*]:stroke-white"
                        : "text-[#D8E3FA]"
                    }`}
                  />
                </span>

                <span className="flex items-center text-[22px]">
                  피킹 리스트 관리
                </span>
              </button>
            </div>
          )}
        </section>
      </nav>
    </aside>
  );
}
