import { useCallback, useEffect, useMemo, useState } from "react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import search_icon from "../../assets/icon/search_icon.svg";
import Header from "../../components/layout/header";
import LpnModal from "../../components/modal/lpn-modal";
import WLpnModal from "../../components/modal/wlpn-modal";
import KLpnModal from "../../components/modal/klpn-modal";

function HistoryView() {
  // API Base URL 상태 관리
  const [baseUrl, setBaseUrl] = useState("");

  const [searchInput, setSearchInput] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [typeList, setTypeList] = useState([]);
  const [selectedType, setSelectedType] = useState("전체");
  const [selectedLpn, setSelectedLpn] = useState(null);
  const [modalType, setModalType] = useState(null);
  const today = new Date();

  const [startDate, setStartDate] = useState(today);
  const [endDate, setEndDate] = useState(today);
  const [selectedRowId, setSelectedRowId] = useState(null);
  const [historyData, setHistoryData] = useState([]);

  /*
   * 1. 컴포넌트 마운트 시 public/config.json 로드
   */
  useEffect(() => {
    const loadConfig = async () => {
      try {
        // window.APP_CONFIG가 이미 존재하는 경우 우선 사용, 없으면 fetch
        if (window.APP_CONFIG?.apiBaseUrl) {
          setBaseUrl(window.APP_CONFIG.apiBaseUrl);
          return;
        }

        const response = await fetch("/config.json");
        if (!response.ok) {
          throw new Error("config.json 로드 실패");
        }
        const config = await response.json();
        if (config?.apiBaseUrl) {
          setBaseUrl(config.apiBaseUrl);
        } else {
          console.error("config.json에 apiBaseUrl이 정의되어 있지 않습니다.");
        }
      } catch (error) {
        console.error("환경 설정 파일 로드 실패:", error);
      }
    };

    loadConfig();
  }, []);

  /*
   * 이력 목록 조회
   */
  const fetchHistoryList = useCallback(
    async (apiBase) => {
      if (!apiBase) return;

      try {
        const formatDate = (date) => {
          const year = date.getFullYear();
          const month = String(date.getMonth() + 1).padStart(2, "0");
          const day = String(date.getDate()).padStart(2, "0");

          return `${year}-${month}-${day}`;
        };

        const response = await fetch(
          `${apiBase}/get/history/list?date_from=${formatDate(startDate)}&date_to=${formatDate(endDate)}`,
          {
            method: "GET",
            headers: {
              Accept: "application/json",
            },
          },
        );

        const result = await response.json();

        if (!response.ok) {
          throw new Error(
            result?.detail ||
              result?.msg ||
              `이력 조회 실패: ${response.status}`,
          );
        }

        setHistoryData(Array.isArray(result.data) ? result.data : []);
      } catch (error) {
        console.error("이력 조회 실패:", error);
        setHistoryData([]);
      }
    },
    [startDate, endDate],
  );

  /*
   * 이력 유형 목록 조회
   */
  const fetchTypeList = useCallback(async (apiBase) => {
    if (!apiBase) return;

    try {
      const response = await fetch(`${apiBase}/get/history/types`, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.detail ||
            result?.msg ||
            `유형 조회 실패 : ${response.status}`,
        );
      }

      const list = Array.isArray(result?.data)
        ? result.data
        : Array.isArray(result)
          ? result
          : [];

      setTypeList(list);
    } catch (error) {
      console.error("유형 조회 실패 :", error);
      setTypeList([]);
    }
  }, []);

  const typeNameMap = useMemo(() => {
    return typeList.reduce((acc, item) => {
      acc[item.code] = item.code_name;
      return acc;
    }, {});
  }, [typeList]);

  /*
   * baseUrl, 날짜 조건 변경 시 데이터 다시 조회
   */
  useEffect(() => {
    if (baseUrl) {
      fetchHistoryList(baseUrl);
      fetchTypeList(baseUrl);
    }
  }, [baseUrl, fetchHistoryList, fetchTypeList]);

  const filteredData = useMemo(() => {
    return historyData.filter((item) => {
      const normalizedSearch = searchTerm.trim().toLowerCase();

      // 유형 필터
      const matchesType =
        selectedType === "전체" || item.txn_type === selectedType;

      // 검색 조건 (LPN 코드, 품목, 엔진 번호, 위치)
      const matchesSearch =
        normalizedSearch === "" ||
        (item.lpn_code ?? "").toLowerCase().includes(normalizedSearch) ||
        (item.item_code ?? "").toLowerCase().includes(normalizedSearch) ||
        (item.item_name ?? "").toLowerCase().includes(normalizedSearch) ||
        (item.engine_no ?? "").toLowerCase().includes(normalizedSearch) ||
        (item.to_location_code ?? "")
          .toLowerCase()
          .includes(normalizedSearch) ||
        (item.from_location_code ?? "")
          .toLowerCase()
          .includes(normalizedSearch);

      return matchesType && matchesSearch;
    });
  }, [historyData, searchTerm, selectedType]);

  const handleSearch = () => {
    setSearchTerm(searchInput);
  };

  const handleRowClick = (item) => {
    setSelectedLpn(item);
    setSelectedRowId(item.txn_seq);

    const modalMap = {
      R: "LPN",
      W: "W-LPN",
      K: "K-LPN",
      D: "LPN",
    };

    setModalType(modalMap[item.lpn_type] ?? null);
  };

  const handleCloseModal = () => {
    setModalType(null);
    setSelectedLpn(null);
  };


  return (
    <div className="flex h-full w-full items-center justify-center">
      <div className="flex h-[1080px] w-[1560px] flex-col gap-[30px] p-[30px]">
        {/* 헤더 영역 */}
        <div className="flex h-[100px] w-[1500px] shrink-0 items-end gap-[30px]">
          <Header category="조회" title="이력 조회" />
        </div>

        {/* 하단 콘텐츠 영역 */}
        <div className="flex h-[890px] w-[1500px] flex-col gap-[30px]">
          {/* 조회 조건 영역 */}
          <div className="flex h-[147px] w-full shrink-0 flex-col justify-between">
            {/* 범위 및 유형 영역 */}
            <div className="flex h-[57px] w-full gap-[100px]">
              {/* 범위 영역 */}
              <div className="flex h-[57px] min-w-0 flex-1 items-center gap-[30px]">
                <span className="shrink-0 text-[32px] font-bold leading-none text-black">
                  범위
                </span>

                {/* 날짜 범위 */}
                <div className="flex w-[548px] shrink-0 items-center gap-[15px]">
                  {/* 시작 날짜 */}
                  <DatePicker
                    selected={startDate}
                    onChange={(date) => {
                      setStartDate(date);

                      // 시작 날짜가 종료 날짜보다 뒤라면 종료 날짜 초기화
                      if (endDate && date && date > endDate) {
                        setEndDate(null);
                      }
                    }}
                    selectsStart
                    startDate={startDate}
                    endDate={endDate}
                    maxDate={endDate}
                    placeholderText="시작 날짜"
                    dateFormat="yyyy-MM-dd"
                    className="h-[57px] w-[250px] cursor-pointer rounded-[10px] border-none bg-[#EBEDF1] px-[30px] text-center text-[24px] font-semibold text-[#A8ADB5] outline-none"
                    calendarClassName="custom-datepicker"
                    popperPlacement="bottom-start"
                    aria-label="시작 날짜"
                  />

                  <span className="flex h-[57px] w-[18px] items-center justify-center text-[24px] font-semibold text-[#717071]">
                    ~
                  </span>

                  {/* 종료 날짜 */}
                  <DatePicker
                    selected={endDate}
                    onChange={(date) => setEndDate(date)}
                    selectsEnd
                    startDate={startDate}
                    endDate={endDate}
                    minDate={startDate}
                    placeholderText="종료 날짜"
                    dateFormat="yyyy-MM-dd"
                    className="h-[57px] w-[250px] cursor-pointer rounded-[10px] border-none bg-[#EBEDF1] px-[30px] text-center text-[24px] font-semibold text-[#A8ADB5] outline-none placeholder:text-[#A8ADB5]"
                    calendarClassName="custom-datepicker"
                    popperPlacement="bottom-start"
                    aria-label="종료 날짜"
                  />
                </div>
              </div>

              {/* 유형 영역 */}
              <div className="flex h-[57px] w-[536px] shrink-0 items-center gap-[30px]">
                <span className="w-[56px] shrink-0 text-[32px] font-bold leading-none text-black">
                  유형
                </span>
                <div className="flex h-[55px] flex-1 items-center rounded-[10px] bg-[#EBEDF1] px-[20px]">
                  <select
                    value={selectedType}
                    onChange={(event) => setSelectedType(event.target.value)}
                    className="h-full w-full cursor-pointer bg-[#EBEDF1] text-center text-[24px] font-semibold text-black outline-none"
                  >
                    <option value="전체">전체</option>

                    {typeList.map((type) => (
                      <option key={type.code} value={type.code}>
                        {type.code_name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* 검색 영역 */}
            <div className="flex h-[70px] w-full gap-[20px]">
              <div className="flex w-[1330px] h-[70px] items-center rounded-[10px] bg-[#EBEDF1] px-[20px] gap-[10px]">
                <input
                  type="text"
                  value={searchInput}
                  onChange={(event) => setSearchInput(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      handleSearch();
                    }
                  }}
                  placeholder="검색 (LPN, 위치 등)"
                  className="h-[30.76px] w-[1237.5px] bg-[#EBEDF1] text-[24px] font-medium text-black outline-none placeholder:text-[#A8ADB5]"
                />
                <button
                  type="button"
                  onClick={() => {
                    handleSearch();
                  }}
                  className="flex h-[38px] w-[37px] items-center justify-center"
                >
                  <img
                    src={search_icon}
                    alt="검색"
                    className="h-[38px] w-[37px]"
                  />
                </button>
              </div>

              <button
                type="button"
                onClick={() => {
                  handleSearch();
                }}
                className="flex w-[150px] items-center justify-center rounded-[10px] bg-[#243659] gap-[20px]"
              >
                <span className="text-[24px] font-semibold text-white">
                  조회
                </span>
              </button>
            </div>
          </div>

          <div className="flex w-full h-[2px] items-center bg-[#EEEEEE]" />

          {/* 리스트 목록 영역 */}
          <div className="flex h-[653px] w-[1500px] gap-[10px]">
            {/* 리스트 본체 */}
            <div className="flex h-[653px] w-[1475px] shrink-0 flex-col overflow-hidden rounded-[10px] border border-[#E8E8E8]">
              {/* 리스트 헤더 */}
              <div className="grid h-[60px] w-[1475px] shrink-0 grid-cols-[95px_150px_180px_200px_120px_300px_430px] items-center bg-[#243659]">
                <div className="text-center text-[24px] font-bold text-white">
                  순번
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  유형
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  자재코드
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  LPN
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  수량
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  위치
                </div>

                <div className="text-center text-[24px] font-bold text-white">
                  일시
                </div>
              </div>

              {/* 리스트 데이터 */}
              <div className="scrollbar-hidden min-h-0 w-[1475px] flex-1 overflow-x-hidden overflow-y-auto">
                {filteredData.length === 0 ? (
                  <div className="flex h-full items-center justify-center">
                    <span className="text-[36px] font-bold text-[#8F949E]">
                      목록 없음
                    </span>
                  </div>
                ) : (
                  filteredData.map((item, index) => (
                    <div
                      key={`${item.txn_seq}-${item.lpn_code}`}
                      onClick={() => handleRowClick(item)}
                      className={`grid h-[60px] w-[1475px] shrink-0 cursor-pointer grid-cols-[95px_150px_180px_200px_120px_300px_430px] items-center transition-colors ${
                        selectedRowId === item.txn_seq
                          ? "bg-[#EBEDF1]"
                          : "bg-white hover:bg-[#EBEDF1]"
                      }
                    `}
                    >
                      <div className="truncate px-[10px] text-center text-[24px] font-normal text-[#202020]">
                        {index + 1}
                      </div>

                      <div className="truncate px-[10px] text-center text-[24px] font-normal text-[#202020]">
                        {typeNameMap[item.txn_type] ?? item.txn_type}
                      </div>

                      <div className="truncate px-[10px] text-center text-[24px] font-normal text-[#202020]">
                        {item.item_code}
                      </div>

                      <div className="truncate px-[10px] text-center text-[24px] font-normal text-[#202020]">
                        {item.lpn_code}
                      </div>

                      <div className="truncate px-[10px] text-center text-[24px] font-normal text-[#202020]">
                        {item.qty}
                      </div>

                      <div className="truncate px-[10px] text-center text-[24px] font-normal text-[#202020]">
                        {item.to_location_code}
                      </div>

                      <div className="whitespace-nowrap px-[10px] text-center text-[24px] font-normal text-[#202020]">
                        {item.txn_date?.replace("T", " ").slice(0, 19)}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
      {modalType === "LPN" && (
        <LpnModal data={selectedLpn} onClose={handleCloseModal} />
      )}

      {modalType === "W-LPN" && (
        <WLpnModal data={selectedLpn} onClose={handleCloseModal} />
      )}

      {modalType === "K-LPN" && (
        <KLpnModal data={selectedLpn} onClose={handleCloseModal} />
      )}
    </div>
  );
}

export default HistoryView;
