import { useEffect, useMemo, useState } from "react";

import rackSectionDetailIcon from "../../assets/icon/rack-section-detail_icon.svg";

function RackSectionDetail({ selectedCell }) {
  // 현재 선택된 LPN 순번
  const [currentLpnIndex, setCurrentLpnIndex] = useState(0);

  // 현재 선택된 LPN 안의 자재 순번
  const [currentItemIndex, setCurrentItemIndex] = useState(0);

  // 다른 셀을 클릭하면 첫 번째 LPN과 첫 번째 자재로 초기화
  useEffect(() => {
    setCurrentLpnIndex(0);
    setCurrentItemIndex(0);
  }, [selectedCell?.location_seq, selectedCell?.locationSeq]);

  // LPN 목록
  const lpnList = useMemo(() => {
    return Array.isArray(selectedCell?.lpnList)
      ? selectedCell.lpnList.slice(0, 5)
      : [];
  }, [selectedCell?.lpnList]);

  // 현재 선택된 LPN
  const currentLpn = lpnList[currentLpnIndex] ?? null;

  // 현재 LPN에 포함된 자재 목록
  const itemList = useMemo(() => {
    return Array.isArray(currentLpn?.items) ? currentLpn.items.slice(0, 5) : [];
  }, [currentLpn]);

  // 현재 LPN이 변경되면 첫 번째 자재로 초기화
  useEffect(() => {
    setCurrentItemIndex(0);
  }, [currentLpnIndex]);

  // 현재 선택된 자재
  const currentItem = itemList[currentItemIndex] ?? null;

  if (!selectedCell) {
    return (
      <div className="flex h-full w-full flex-col items-center justify-center gap-[50px] px-[50px]">
        <div className="flex h-[250px] w-[250px] items-center justify-center">
          <img
            src={rackSectionDetailIcon}
            alt="선택된 로케이션 없음"
            className="h-[227.07px] w-[230px] object-contain"
          />
        </div>

        <span className="w-[535px] text-center text-[36px] font-extrabold text-[#243659]">
          조회하실 랙 구역을 선택해 주세요.
        </span>
      </div>
    );
  }

  // 사용 불가 여부
  const isUnavailable =
    selectedCell.enable_yn === false ||
    selectedCell.enable_yn === 0 ||
    selectedCell.enable_yn === "N" ||
    selectedCell.available === false;

  // 사용 중 여부
  const isUsed =
    selectedCell.status === "USED" ||
    Number(selectedCell.lpn_cnt ?? selectedCell.lpnCount ?? 0) > 0 ||
    lpnList.length > 0;

  // 셀 상태
  const status = isUnavailable
    ? {
        label: "사용 불가",
        className: "bg-[#C12B2B]",
      }
    : isUsed
      ? {
          label: "사용 중",
          className: "bg-[#40CB7C]",
        }
      : {
          label: "비었음",
          className: "bg-[#8F949E]",
        };

  const rackCode = selectedCell.rack_code ?? selectedCell.rackCode ?? "-";

  const locationCode =
    selectedCell.location_code ??
    selectedCell.locationCode ??
    selectedCell.cellCode ??
    "-";

  return (
    <div className="flex h-full w-[535px] flex-col">
      {/* 상세정보 헤더 */}
      <div className="flex h-[50px] w-[535px] gap-[10px]">
        <span className="h-[45px] w-[415px] text-[36px] font-extrabold text-[#243659]">
          선택 위치 정보
        </span>

        <div
          className={`flex h-[50px] w-[110px] items-center justify-center rounded-[10px] p-[10px] text-[22px] font-semibold text-white ${status.className}`}
        >
          {status.label}
        </div>
      </div>

      <div className="my-[28px] h-[2px] w-[535px] shrink-0 bg-white" />

      {selectedCell.detailLoading ? (
        <div className="flex min-h-[485px] w-[535px] items-center justify-center">
          <span className="text-[30px] font-bold text-[#747983]">
            상세정보를 불러오는 중입니다.
          </span>
        </div>
      ) : (
        <>
          <div className="flex min-h-[485px] w-[535px] flex-col justify-center gap-[20px]">
            <DetailRow label="랙 코드" value={rackCode ?? "-"} />

            <DetailRow label="상세 위치" value={locationCode ?? "-"} />

            <DetailRow label="자재코드" value={currentItem?.item_code ?? "-"} />

            <DetailRow label="LPN" value={currentLpn?.lpn_code ?? "-"} />

            <DetailRow
              label="입고일자"
              value={formatDate(currentLpn?.receipt_date)}
            />

            <DetailRow label="자재 수량" value={currentLpn?.total_qty ?? "-"} />

            <DetailRow
              label="세척 여부"
              value={formatBoolean(currentItem?.washing_yn)}
            />

            {/* 자재 목록 수(itemList.length)가 1개 이하일 때만 분할 여부를 표시 */}
            {itemList.length <= 1 && (
              <DetailRow
                label="분할 여부"
                value={formatBoolean(currentLpn?.split_yn)}
              />
            )}
          </div>

          {selectedCell.detailError && (
            <div className="mb-[10px] w-[535px] text-center text-[18px] font-semibold text-[#C12B2B]">
              {selectedCell.detailError}
            </div>
          )}

          {/* LPN이 여러 개일 때 LPN 선택 */}
          {lpnList.length > 1 && (
            <div className="mt-auto flex w-[535px] flex-col items-center gap-[8px]">
              <span className="text-[18px] font-bold text-[#243659]">
                LPN 선택
              </span>

              <div className="flex h-[40px] items-center justify-center gap-[24px]">
                {lpnList.map((lpn, index) => {
                  const isActive = currentLpnIndex === index;

                  return (
                    <button
                      key={lpn.lpn_master_seq ?? lpn.lpn_code ?? index}
                      type="button"
                      aria-label={`${index + 1}번째 LPN 보기`}
                      aria-pressed={isActive}
                      onClick={() => setCurrentLpnIndex(index)}
                      className={`shrink-0 rounded-full transition-all duration-200 ${
                        isActive
                          ? "h-[30px] w-[30px] bg-[#3863BA]"
                          : "h-[21px] w-[21px] bg-[#9A9FA8]"
                      }`}
                    />
                  );
                })}
              </div>
            </div>
          )}

          {/* 한 LPN에 자재가 여러 개일 때 자재 선택 */}
          {itemList.length > 1 && (
            <div className="mt-[50px] flex w-[535px] flex-col items-center">
              <div className="flex h-[40px] items-center justify-center gap-[24px]">
                {itemList.map((item, index) => {
                  const isActive = currentItemIndex === index;

                  return (
                    <button
                      key={item.lpn_detail_seq ?? item.item_seq ?? index}
                      type="button"
                      aria-label={`${index + 1}번째 자재 보기`}
                      aria-pressed={isActive}
                      onClick={() => setCurrentItemIndex(index)}
                      className={`shrink-0 rounded-full transition-all duration-200 ${
                        isActive
                          ? "h-[30px] w-[30px] bg-[#3863BA]"
                          : "h-[21px] w-[21px] bg-[#9A9FA8]"
                      }`}
                    />
                  );
                })}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

// 상세정보 한 행
function DetailRow({ label, value }) {
  return (
    <div className="grid w-full grid-cols-[190px_1fr] items-center gap-[20px]">
      <span className="text-[28px] font-bold text-[#243659]">{label}</span>

      <div className="ml-auto flex h-[50px] w-[305px] items-center justify-center overflow-hidden rounded-[10px] bg-white px-[15px] text-center text-[24px] font-normal text-black">
        <span className="w-full truncate" title={String(value ?? "-")}>
          {value ?? "-"}
        </span>
      </div>
    </div>
  );
}

// boolean 값을 Y/N으로 표시
function formatBoolean(value) {
  if (
    value === true ||
    value === 1 ||
    value === "1" ||
    value === "Y" ||
    value === "y"
  ) {
    return "Y";
  }

  if (
    value === false ||
    value === 0 ||
    value === "0" ||
    value === "N" ||
    value === "n"
  ) {
    return "N";
  }

  return "-";
}

function formatDate(value) {
  if (!value) {
    return "-";
  }

  const dateString = String(value);

  const match = dateString.match(/^\d{4}-\d{2}-\d{2}/);

  return match ? match[0] : dateString;
}

export default RackSectionDetail;