import { useEffect, useMemo, useRef, useState } from "react";
import Header from "../../components/layout/header";
import left_arrow_icon from "../../assets/icon/left_arrow_icon.svg";
import right_arrow_icon from "../../assets/icon/right_arrow_icon.svg";
import more_icon from "../../assets/icon/more_icon.svg";
import select_icon from "../../assets/icon/select_icon.svg";
import PickingDetailModal from "../../components/modal/picking-detail-modal";

const ROW_HEIGHT = 60;

const SEND_PICK_CODE = "PICK-260801-0001";
const RECEIVE_PICK_CODE = "PICK-260802-0002";

const EMPTY_MOVE_MODAL = {
  isOpen: false,
  type: null,
  direction: null,
  items: [],
  quantities: [],
  sourcePickCode: "",
  targetPickCode: "",
};

const EMPTY_DRAG_STATE = {
  listType: null,
  draggedItemId: null,
  movingItemIds: [],
  dragOverIndex: null,
};

const EMPTY_DRAG_PREVIEW = {
  visible: false,
  x: 0,
  y: 0,
  width: 0,
  item: null,
  count: 0,
};

const SELECT_OPTIONS = [
  { value: "", label: "선택" },
  { value: "all", label: "전체" },
  { value: "washing", label: "세척" },
  { value: "non-washing", label: "비세척" },
];

const INITIAL_SEND_LIST = [
  {
    id: 1,
    item_code: "MAT-240801",
    quantity: 12,
    washing_yn: "Y",
  },
  {
    id: 2,
    item_code: "MAT-240802",
    quantity: 5,
    washing_yn: "N",
  },
  {
    id: 3,
    item_code: "MAT-240803",
    quantity: 32,
    washing_yn: "Y",
  },
  {
    id: 4,
    item_code: "MAT-240804",
    quantity: 18,
    washing_yn: "N",
  },
  {
    id: 5,
    item_code: "MAT-240805",
    quantity: 7,
    washing_yn: "Y",
  },
  {
    id: 6,
    item_code: "MAT-240806",
    quantity: 40,
    washing_yn: "N",
  },
  {
    id: 7,
    item_code: "MAT-240807",
    quantity: 22,
    washing_yn: "Y",
  },
  {
    id: 8,
    item_code: "MAT-240808",
    quantity: 16,
    washing_yn: "N",
  },
  {
    id: 9,
    item_code: "MAT-240809",
    quantity: 9,
    washing_yn: "Y",
  },
  {
    id: 10,
    item_code: "MAT-240810",
    quantity: 27,
    washing_yn: "N",
  },
  {
    id: 11,
    item_code: "MAT-240811",
    quantity: 14,
    washing_yn: "Y",
  },
  {
    id: 12,
    item_code: "MAT-240812",
    quantity: 31,
    washing_yn: "N",
  },
];

const INITIAL_RECEIVE_LIST = [
  {
    id: 101,
    item_code: "MAT-250001",
    quantity: 11,
    washing_yn: "Y",
  },
  {
    id: 102,
    item_code: "MAT-250002",
    quantity: 20,
    washing_yn: "N",
  },
  {
    id: 103,
    item_code: "MAT-250003",
    quantity: 8,
    washing_yn: "Y",
  },
  {
    id: 104,
    item_code: "MAT-250004",
    quantity: 50,
    washing_yn: "Y",
  },
];

function PickingListPartition() {
  // 왼쪽과 오른쪽 목록의 필터값
  const [sendFilter, setSendFilter] = useState("");
  const [receiveFilter, setReceiveFilter] = useState("");

  // 왼쪽은 보낼 피킹 리스트, 오른쪽은 받을 피킹 리스트
  const [sendList, setSendList] = useState(INITIAL_SEND_LIST);
  const [receiveList, setReceiveList] = useState(INITIAL_RECEIVE_LIST);

  // 각 리스트에서 체크한 행 ID
  const [selectedSendIds, setSelectedSendIds] = useState([]);
  const [selectedReceiveIds, setSelectedReceiveIds] = useState([]);

  // 변경 사항 적용 버튼 활성화 여부
  const [isChanged, setIsChanged] = useState(false);

  // 분할 수량 지정, 분할 확인, 통합 확인 모달을 하나의 상태로 관리
  const [moveModal, setMoveModal] = useState(EMPTY_MOVE_MODAL);

  // 좌우 이동이 한 번이라도 실행되었는지 확인
  // 드래그 순서 변경만 한 경우에는 분할·통합 모달을 띄우지 않기 위해 사용
  const [hasListMove, setHasListMove] = useState(false);
  const hasListMoveRef = useRef(false);

  // 현재 드래그 상태
  const [dragState, setDragState] = useState(EMPTY_DRAG_STATE);

  // 커스텀 드래그 미리보기
  const [dragPreview, setDragPreview] = useState(EMPTY_DRAG_PREVIEW);

  // 드래그 상태 참조
  const dragStateRef = useRef(EMPTY_DRAG_STATE);
  const transparentDragImageRef = useRef(null);

  // 피킹 리스트 관리 화면에서 선택한 데이터를 불러옴
  useEffect(() => {
    try {
      const savedData = sessionStorage.getItem("selectedPickingList");

      if (!savedData) {
        return;
      }

      const parsedData = JSON.parse(savedData);

      if (!Array.isArray(parsedData)) {
        return;
      }

      const normalizedData = parsedData.map((item, index) => ({
        ...item,
        id: item.id ?? item.seq ?? index + 1,
        item_code: item.item_code ?? item.material_code ?? item.order_no ?? "-",
        quantity: item.quantity ?? item.qty ?? item.material_count ?? 0,
        washing_yn:
          item.washing_yn === true ||
          item.washing_yn === 1 ||
          item.washing_yn === "Y"
            ? "Y"
            : "N",
      }));

      setSendList(normalizedData);
    } catch (error) {
      console.error("선택된 피킹 리스트 불러오기 실패:", error);
    }
  }, []);

  // 기본 드래그 이미지 숨김
  useEffect(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 1;
    canvas.height = 1;

    transparentDragImageRef.current = canvas;
  }, []);

  // 드래그 미리보기 위치 갱신
  useEffect(() => {
    if (!dragPreview.visible) {
      return undefined;
    }

    const handleWindowDragOver = (event) => {
      if (event.clientX === 0 && event.clientY === 0) {
        return;
      }

      setDragPreview((previous) => ({
        ...previous,
        x: event.clientX,
        y: event.clientY,
      }));
    };

    window.addEventListener("dragover", handleWindowDragOver);

    return () => {
      window.removeEventListener("dragover", handleWindowDragOver);
    };
  }, [dragPreview.visible]);

  // 전체·세척·비세척 조건으로 목록 필터링
  const filterList = (list, filterValue) => {
    if (!filterValue || filterValue === "all") {
      return list;
    }

    if (filterValue === "washing") {
      return list.filter((item) => item.washing_yn === "Y");
    }

    if (filterValue === "non-washing") {
      return list.filter((item) => item.washing_yn === "N");
    }

    return list;
  };

  const filteredSendList = useMemo(
    () => filterList(sendList, sendFilter),
    [sendList, sendFilter],
  );

  const filteredReceiveList = useMemo(
    () => filterList(receiveList, receiveFilter),
    [receiveList, receiveFilter],
  );

  // 왼쪽 행 선택 또는 선택 해제
  const handleSelectSendItem = (itemId) => {
    setSelectedSendIds((previousIds) =>
      previousIds.includes(itemId)
        ? previousIds.filter((id) => id !== itemId)
        : [...previousIds, itemId],
    );
  };

  // 오른쪽 행 선택 또는 선택 해제
  const handleSelectReceiveItem = (itemId) => {
    setSelectedReceiveIds((previousIds) =>
      previousIds.includes(itemId)
        ? previousIds.filter((id) => id !== itemId)
        : [...previousIds, itemId],
    );
  };

  // 현재 왼쪽 필터 결과 전체 선택 또는 해제
  const handleSelectAllSend = () => {
    const visibleIds = filteredSendList.map((item) => item.id);

    const isAllSelected =
      visibleIds.length > 0 &&
      visibleIds.every((id) => selectedSendIds.includes(id));

    if (isAllSelected) {
      setSelectedSendIds((previousIds) =>
        previousIds.filter((id) => !visibleIds.includes(id)),
      );
      return;
    }

    setSelectedSendIds((previousIds) => [
      ...new Set([...previousIds, ...visibleIds]),
    ]);
  };

  // 현재 오른쪽 필터 결과 전체 선택 또는 해제
  const handleSelectAllReceive = () => {
    const visibleIds = filteredReceiveList.map((item) => item.id);

    const isAllSelected =
      visibleIds.length > 0 &&
      visibleIds.every((id) => selectedReceiveIds.includes(id));

    if (isAllSelected) {
      setSelectedReceiveIds((previousIds) =>
        previousIds.filter((id) => !visibleIds.includes(id)),
      );
      return;
    }

    setSelectedReceiveIds((previousIds) => [
      ...new Set([...previousIds, ...visibleIds]),
    ]);
  };

  // 이동 수량 지정 모달 열기
  const handleOpenMoveQuantityModal = (direction) => {
    const isToReceive = direction === "toReceive";
    const sourceList = isToReceive ? sendList : receiveList;
    const selectedIds = isToReceive ? selectedSendIds : selectedReceiveIds;

    const selectedItems = sourceList.filter((item) =>
      selectedIds.includes(item.id),
    );

    if (selectedItems.length === 0) {
      return;
    }

    setMoveModal({
      isOpen: true,
      type: "partitionQuantity",
      direction,
      items: selectedItems,
      quantities: [],
      sourcePickCode: isToReceive ? SEND_PICK_CODE : RECEIVE_PICK_CODE,
      targetPickCode: isToReceive ? RECEIVE_PICK_CODE : SEND_PICK_CODE,
    });
  };

  // 이동 수량 지정 모달에서 확인했을 때 실제 이동 처리
  const handleConfirmMoveQuantities = (quantities) => {
    hasListMoveRef.current = true;
    setHasListMove(true);

    applyMove(quantities);
  };

  // 리스트 이동 처리
  const applyMove = (confirmedQuantities) => {
    const { direction, items } = moveModal;

    const quantities = confirmedQuantities;

    const isToReceive = direction === "toReceive";

    const quantityMap = new Map(
      quantities.map((entry) => [entry.id, Number(entry.quantity)]),
    );

    const updateSourceList = (currentList) =>
      currentList
        .map((item) => {
          const moveQuantity = quantityMap.get(item.id);

          if (moveQuantity === undefined) {
            return item;
          }

          const remainingQuantity = Number(item.quantity) - moveQuantity;

          if (remainingQuantity <= 0) {
            return null;
          }

          return {
            ...item,
            quantity: remainingQuantity,
          };
        })
        .filter(Boolean);

    const updateTargetList = (currentList) => {
      const nextList = currentList.map((item) => ({ ...item }));

      items.forEach((item) => {
        const moveQuantity = quantityMap.get(item.id) ?? 0;
        const sameItemIndex = nextList.findIndex(
          (targetItem) => targetItem.item_code === item.item_code,
        );

        if (sameItemIndex >= 0) {
          nextList[sameItemIndex] = {
            ...nextList[sameItemIndex],
            quantity: Number(nextList[sameItemIndex].quantity) + moveQuantity,
          };
          return;
        }

        nextList.push({
          ...item,
          // 양쪽 리스트에서 id 충돌이 나지 않도록 이동 행에 새 id 부여
          id: `${direction}-${item.id}-${Date.now()}-${nextList.length}`,
          quantity: moveQuantity,
        });
      });

      return nextList;
    };

    if (isToReceive) {
      setSendList(updateSourceList);
      setReceiveList(updateTargetList);
      setSelectedSendIds([]);
    } else {
      setReceiveList(updateSourceList);
      setSendList(updateTargetList);
      setSelectedReceiveIds([]);
    }

    setIsChanged(true);
    setMoveModal(EMPTY_MOVE_MODAL);
  };

  // 이동 관련 모달 닫기
  const handleCloseMoveModal = () => {
    setMoveModal(EMPTY_MOVE_MODAL);
  };

  // 분할 또는 통합 확인 모달에서 최종 확인했을 때 실제 저장 처리
  const handleConfirmSaveChanges = () => {
    const result = {
      sendList,
      receiveList,
      changeType:
        sendList.length === 0 || receiveList.length === 0
          ? "merge"
          : "partition",
    };

    console.log("최종 저장할 분할 및 통합 데이터:", result);

    // API 연결 위치
    // await updatePickingPartition(result);

    sessionStorage.setItem("pickingPartitionResult", JSON.stringify(result));

    setIsChanged(false);

    setHasListMove(false);
    hasListMoveRef.current = false;

    setMoveModal(EMPTY_MOVE_MODAL);
  };

  // 드래그 상태 전체 초기화
  const resetDragState = () => {
    dragStateRef.current = EMPTY_DRAG_STATE;
    setDragState(EMPTY_DRAG_STATE);
    setDragPreview(EMPTY_DRAG_PREVIEW);
  };

  // 점 6개 아이콘에서 드래그를 시작할 때 실행
  const handleDragStart = ({
    event,
    listType,
    item,
    items,
    selectedIds,
    panelWidth,
  }) => {
    // 체크된 행의 핸들을 잡으면 체크된 행 전체를 현재 순서대로 이동
    const movingItemIds = selectedIds.includes(item.id)
      ? items
          .filter((currentItem) => selectedIds.includes(currentItem.id))
          .map((currentItem) => currentItem.id)
      : [item.id];

    const nextDragState = {
      listType,
      draggedItemId: item.id,
      movingItemIds,
      dragOverIndex: null,
    };

    dragStateRef.current = nextDragState;
    setDragState(nextDragState);

    setDragPreview({
      visible: true,
      x: event.clientX,
      y: event.clientY,
      width: Math.max(panelWidth - 20, 0),
      item,
      count: movingItemIds.length,
    });

    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData(
      "application/json",
      JSON.stringify({
        listType,
        movingItemIds,
      }),
    );

    if (transparentDragImageRef.current) {
      event.dataTransfer.setDragImage(transparentDragImageRef.current, 0, 0);
    }
  };

  // 마우스가 위치한 행의 중간값을 기준으로 삽입 위치 계산
  const handleListDragOver = ({ event, listType, listElement, itemCount }) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";

    // 다른 패널로 드래그해서 순서를 변경하는 것은 차단
    if (
      dragStateRef.current.listType !== listType ||
      dragStateRef.current.movingItemIds.length === 0
    ) {
      return;
    }

    const visibleRows = Array.from(
      listElement.querySelectorAll(
        '[data-partition-row][data-dragging="false"]',
      ),
    );

    let nextIndex = itemCount;

    for (const row of visibleRows) {
      const rect = row.getBoundingClientRect();
      const middleY = rect.top + rect.height / 2;

      if (event.clientY < middleY) {
        nextIndex = Number(row.dataset.rowIndex);
        break;
      }
    }

    if (dragStateRef.current.dragOverIndex === nextIndex) {
      return;
    }

    const nextDragState = {
      ...dragStateRef.current,
      dragOverIndex: nextIndex,
    };

    dragStateRef.current = nextDragState;
    setDragState(nextDragState);
  };

  // 드롭된 위치에 이동 행들을 삽입하여 해당 리스트 순서 변경
  const handleDrop = ({ event, listType }) => {
    event.preventDefault();
    event.stopPropagation();

    const {
      listType: sourceListType,
      movingItemIds,
      dragOverIndex,
    } = dragStateRef.current;

    if (
      sourceListType !== listType ||
      dragOverIndex === null ||
      movingItemIds.length === 0
    ) {
      resetDragState();
      return;
    }

    const reorderList = (currentList) => {
      const movingItems = currentList.filter((item) =>
        movingItemIds.includes(item.id),
      );

      const remainingItems = currentList.filter(
        (item) => !movingItemIds.includes(item.id),
      );

      // 이동 행이 목표 위치보다 앞에 있던 개수만큼 인덱스를 보정
      const removedBeforeTarget = currentList
        .slice(0, dragOverIndex)
        .filter((item) => movingItemIds.includes(item.id)).length;

      const adjustedIndex = Math.max(
        0,
        Math.min(dragOverIndex - removedBeforeTarget, remainingItems.length),
      );

      const nextList = [...remainingItems];
      nextList.splice(adjustedIndex, 0, ...movingItems);

      return nextList;
    };

    if (listType === "send") {
      setSendList(reorderList);
    } else {
      setReceiveList(reorderList);
    }

    setIsChanged(true);
    resetDragState();
  };

  // 드롭하지 않고 드래그가 끝난 경우에도 상태 초기화
  const handleDragEnd = () => {
    resetDragState();
  };

  // 변경 사항 적용
  const handleApplyChanges = () => {
    if (!isChanged || !hasListMoveRef.current) {
      return;
    }

    const isMerge = sendList.length === 0 || receiveList.length === 0;

    setMoveModal((previous) => ({
      ...previous,
      isOpen: true,
      type: isMerge ? "mergeConfirm" : "partitionConfirm",
      sourcePickCode: previous.sourcePickCode || SEND_PICK_CODE,
      targetPickCode: previous.targetPickCode || RECEIVE_PICK_CODE,
    }));
  };

  const isAllSendSelected =
    filteredSendList.length > 0 &&
    filteredSendList.every((item) => selectedSendIds.includes(item.id));

  const isAllReceiveSelected =
    filteredReceiveList.length > 0 &&
    filteredReceiveList.every((item) => selectedReceiveIds.includes(item.id));

  return (
    <div className="flex h-full w-full items-center justify-center">
      <div className="flex h-[1080px] w-[1560px] flex-col gap-[30px] p-[30px]">
        {/* 헤더 */}
        <div className="flex h-[100px] w-[1500px] shrink-0 items-end gap-[30px]">
          <Header
            category="관리"
            parentTitle="피킹 리스트 관리"
            title="리스트 분할 및 통합"
          />
        </div>

        {/* 콘텐츠 */}
        <div className="flex h-[890px] w-[1500px] flex-col gap-[30px]">
          {/* 변경 사항 적용 버튼 */}
          <div className="flex h-[70px] w-full shrink-0 justify-end">
            <button
              type="button"
              onClick={handleApplyChanges}
              disabled={!isChanged}
              className={`flex h-[70px] w-[177px] shrink-0 items-center justify-center rounded-[10px] text-[24px] font-semibold ${
                isChanged
                  ? "cursor-pointer bg-[#243659] text-white"
                  : "cursor-not-allowed bg-[#E9EBEF] text-[#A8ADB5]"
              }`}
            >
              변경 사항 적용
            </button>
          </div>

          <div className="h-[2px] w-full shrink-0 bg-[#EEEEEE]" />

          {/* 좌우 피킹 리스트 */}
          <div className="flex h-[730px] w-full items-start gap-[30px]">
            <PickingPartitionPanel
              listType="send"
              title="보낼 피킹 리스트"
              filterValue={sendFilter}
              onFilterChange={setSendFilter}
              items={filteredSendList}
              selectedIds={selectedSendIds}
              onSelectItem={handleSelectSendItem}
              onSelectAll={handleSelectAllSend}
              isAllSelected={isAllSendSelected}
              dragState={dragState}
              onDragStart={handleDragStart}
              onListDragOver={handleListDragOver}
              onDrop={handleDrop}
              onDragEnd={handleDragEnd}
            />

            {/* 선택 행을 양쪽 목록으로 이동하는 버튼 */}
            <div className="flex h-full w-[80px] shrink-0 flex-col items-center justify-center gap-[30px]">
              <button
                type="button"
                onClick={() => handleOpenMoveQuantityModal("toReceive")}
                disabled={selectedSendIds.length === 0}
                className={`flex h-[80px] w-[80px] border border-[#EBEDF1] items-center justify-center rounded-[10px] gap-[10px] ${
                  selectedSendIds.length > 0
                    ? "cursor-pointer bg-[#E9ECF2]"
                    : "cursor-not-allowed bg-[#F0F1F4]"
                }`}
                aria-label="받는 피킹 리스트로 이동"
              >
                <img
                  src={right_arrow_icon}
                  alt=""
                  draggable={false}
                  className="h-[55px] w-[42px]"
                />
              </button>

              <button
                type="button"
                onClick={() => handleOpenMoveQuantityModal("toSend")}
                disabled={selectedReceiveIds.length === 0}
                className={`flex h-[80px] w-[80px] border border-[#EBEDF1] items-center justify-center rounded-[10px] ${
                  selectedReceiveIds.length > 0
                    ? "cursor-pointer bg-[#E9ECF2]"
                    : "cursor-not-allowed bg-[#F0F1F4]"
                }`}
                aria-label="보내는 피킹 리스트로 이동"
              >
                <img
                  src={left_arrow_icon}
                  alt=""
                  draggable={false}
                  className="h-[55px] w-[42px]"
                />
              </button>
            </div>

            <PickingPartitionPanel
              listType="receive"
              title="받을 피킹 리스트"
              filterValue={receiveFilter}
              onFilterChange={setReceiveFilter}
              items={filteredReceiveList}
              selectedIds={selectedReceiveIds}
              onSelectItem={handleSelectReceiveItem}
              onSelectAll={handleSelectAllReceive}
              isAllSelected={isAllReceiveSelected}
              dragState={dragState}
              onDragStart={handleDragStart}
              onListDragOver={handleListDragOver}
              onDrop={handleDrop}
              onDragEnd={handleDragEnd}
            />
          </div>

          {/* 실제 행 형태의 불투명 커스텀 드래그 미리보기 */}
          {dragPreview.visible && dragPreview.item && (
            <div
              className="pointer-events-none fixed z-[10000] grid h-[60px] grid-cols-[95px_171.67px_171.67px_171.67px_70px] items-center overflow-hidden rounded-[14px] border border-[#D7DADF] bg-[#F1F2F4] shadow-[0_5px_16px_rgba(0,0,0,0.22)]"
              style={{
                left: `${dragPreview.x}px`,
                top: `${dragPreview.y}px`,
                width: `${dragPreview.width}px`,
                transform: "translate(calc(-100% + 42px), -50%)",
              }}
            >
              <div className="flex items-center justify-center">
                <input
                  type="checkbox"
                  checked
                  readOnly
                  tabIndex={-1}
                  className="pointer-events-none h-[20px] w-[20px]"
                />
              </div>

              <div className="truncate px-[10px] text-center text-[22px] text-[#222222]">
                {dragPreview.item.item_code || "-"}
              </div>

              <div className="truncate px-[10px] text-center text-[22px] text-[#222222]">
                {dragPreview.item.quantity ?? "-"}
              </div>

              <div className="truncate px-[10px] text-center text-[22px] text-[#222222]">
                {dragPreview.item.washing_yn || "-"}
              </div>

              <div className="flex items-center justify-center">
                <img
                  src={more_icon}
                  alt=""
                  draggable={false}
                  className="h-[24px] w-[24px]"
                />
              </div>

              {dragPreview.count > 1 && (
                <div className="absolute right-[7px] top-[3px] flex h-[25px] min-w-[25px] items-center justify-center rounded-full bg-[#243659] px-[6px] text-[14px] font-bold text-white">
                  {dragPreview.count}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* 분할 수량 지정 / 분할 확인 / 통합 확인 모달 */}
      <PickingDetailModal
        isOpen={moveModal.isOpen}
        modalType={moveModal.type}
        data={{
          items: moveModal.items,
          quantities: moveModal.quantities,
          sourcePickCode: moveModal.sourcePickCode,
          targetPickCode: moveModal.targetPickCode,
        }}
        onClose={handleCloseMoveModal}
        onConfirmQuantities={handleConfirmMoveQuantities}
        onConfirmPartition={handleConfirmSaveChanges}
        onConfirmMerge={handleConfirmSaveChanges}
      />
    </div>
  );
}

// 좌우에서 공통으로 사용하는 피킹 리스트 패널
function PickingPartitionPanel({
  listType,
  title,
  filterValue,
  onFilterChange,
  items,
  selectedIds,
  onSelectItem,
  onSelectAll,
  isAllSelected,
  dragState,
  onDragStart,
  onListDragOver,
  onDrop,
  onDragEnd,
}) {
  const listRef = useRef(null);
  const panelRef = useRef(null);

  const isCurrentListDragging = dragState.listType === listType;

  const placeholderHeight = Math.max(
    dragState.movingItemIds.length * ROW_HEIGHT,
    ROW_HEIGHT,
  );

  return (
    <div
      ref={panelRef}
      className="flex h-[730px] min-w-0 flex-1 flex-col gap-[30px]"
    >
      {/* 리스트 제목과 필터 선택박스 */}
      <div className="flex h-[55px] w-full items-center gap-[30px]">
        <h2 className="shrink-0 text-[32px] font-semibold text-black">
          {title}
        </h2>

        <div className="relative w-[439px] flex-1">
          <select
            value={filterValue}
            onChange={(event) => onFilterChange(event.target.value)}
            className="h-[55px] w-full cursor-pointer appearance-none rounded-[10px] bg-[#EBEDF1] px-[20px] py-[10px] text-center text-[28px] font-medium text-black outline-none"
            aria-label={`${title} 분류 선택`}
          >
            {SELECT_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>

          {/* select 화살표 아이콘 */}
          <div className="pointer-events-none absolute right-[20px] top-1/2 -translate-y-1/2">
            <img
              src={select_icon}
              alt=""
              draggable={false}
              className="h-[18px] w-[18px]"
            />
          </div>
        </div>
      </div>

      {/* 리스트 테두리 */}
      <div className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-[10px] border border-[#DBDBDB]">
        {/* 리스트 헤더 */}
        <div className="grid h-[60px] w-full shrink-0 grid-cols-[95px_171.67px_171.67px_171.67px_70px] items-center bg-[#243659]">
          <div className="text-center text-[22px] font-bold text-white">
            선택
          </div>

          <div className="text-center text-[22px] font-bold text-white">
            자재 코드
          </div>

          <div className="text-center text-[22px] font-bold text-white">
            수량
          </div>

          <div className="text-center text-[22px] font-bold text-white">
            세척 여부
          </div>

          <div />
        </div>

        {/* 드래그와 드롭을 처리하는 실제 목록 */}
        <div
          ref={listRef}
          onDragOver={(event) =>
            onListDragOver({
              event,
              listType,
              listElement: listRef.current,
              itemCount: items.length,
            })
          }
          onDrop={(event) => onDrop({ event, listType })}
          className="hide-scrollbar min-h-0 flex-1 overflow-y-auto bg-white"
        >
          {items.length > 0 ? (
            items.map((item, index) => {
              const isSelected = selectedIds.includes(item.id);

              const isDragging =
                isCurrentListDragging &&
                dragState.movingItemIds.includes(item.id);

              return (
                <div key={item.id}>
                  {/* 현재 들어갈 위치를 점선 박스로 표시 */}
                  {isCurrentListDragging &&
                    dragState.dragOverIndex === index && (
                      <div
                        className="mx-[10px] rounded-[14px] border-2 border-dashed border-[#C7CBD1] bg-white"
                        style={{
                          height: `${placeholderHeight}px`,
                        }}
                      />
                    )}

                  <div
                    data-partition-row
                    data-row-index={index}
                    data-dragging={isDragging ? "true" : "false"}
                    onClick={() => onSelectItem(item.id)}
                    className={`grid w-full h-[90px] cursor-pointer grid-cols-[95px_171.67px_171.67px_171.67px_70px] items-center overflow-hidden  ${
                      isDragging
                        ? "h-0 opacity-0"
                        : isSelected
                          ? "h-[60px] bg-[#F1F7FF] opacity-100"
                          : "h-[60px] bg-white opacity-100"
                    }`}
                  >
                    <div className="flex items-center justify-center">
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => onSelectItem(item.id)}
                        onClick={(event) => event.stopPropagation()}
                        className="h-[27.41px] w-[26.93px] cursor-pointer"
                        aria-label={`${item.item_code} 선택`}
                      />
                    </div>

                    <div className="truncate px-[10px] text-center text-[22px] text-[#222222]">
                      {item.item_code || "-"}
                    </div>

                    <div className="truncate px-[10px] text-center text-[22px] text-[#222222]">
                      {item.quantity ?? "-"}
                    </div>

                    <div className="truncate px-[10px] text-center text-[22px] text-[#222222]">
                      {item.washing_yn || "-"}
                    </div>

                    {/* 점 6개 아이콘에서만 드래그 시작 */}
                    <div className="flex items-center justify-center">
                      <div
                        draggable
                        onMouseDown={(event) => event.stopPropagation()}
                        onClick={(event) => event.stopPropagation()}
                        onDragStart={(event) => {
                          event.stopPropagation();

                          onDragStart({
                            event,
                            listType,
                            item,
                            items,
                            selectedIds,
                            panelWidth:
                              panelRef.current?.getBoundingClientRect().width ??
                              650,
                          });
                        }}
                        onDragEnd={onDragEnd}
                        className="flex h-[50px] w-[50px] cursor-grab select-none items-center justify-center active:cursor-grabbing"
                      >
                        <img
                          src={more_icon}
                          alt="순서 변경"
                          draggable={false}
                          className="pointer-events-none h-[24px] w-[24px] select-none"
                        />
                      </div>
                    </div>
                  </div>
                </div>
              );
            })
          ) : (
            <div className="flex h-full min-h-[150px] items-center justify-center text-[22px] text-[#A8ADB5]">
              {/* 피킹 리스트가 없습니다. */}
            </div>
          )}

          {/* 리스트 마지막 위치로 드롭할 때 표시 */}
          {isCurrentListDragging &&
            dragState.dragOverIndex === items.length && (
              <div
                className="mx-[10px] rounded-[14px] border-2 border-dashed border-[#C7CBD1] bg-white"
                style={{
                  height: `${placeholderHeight}px`,
                }}
              />
            )}

          <div className="h-[20px] w-full" />
        </div>
      </div>
    </div>
  );
}

export default PickingListPartition;
