function RackSection({ rackData, selectedCell, loadingCellSeq, onCellClick }) {
  const cells = Array.isArray(rackData?.cells) ? rackData.cells : [];

  const loadedCellCount =
    rackData?.used_cell != null
      ? Number(rackData.used_cell)
      : cells.filter((cell) => {
          return Number(cell.lpn_cnt ?? 0) > 0;
        }).length;

  // 현재 랙 고유번호
  const rackSeq = rackData?.rack_seq ?? rackData?.seq ?? rackData?.id;

  // 현재 선택한 셀인지 확인
  const isSelectedCell = (cell) => {
    const cellLocationSeq = cell.location_seq;

    // 현재 선택된 셀의 고유번호
    const selectedLocationSeq =
      selectedCell?.location_seq ??
      selectedCell?.locationSeq ??
      selectedCell?.seq ??
      selectedCell?.id;
    // 현재 선택된 랙의 고유번호
    const selectedRackSeq =
      selectedCell?.rack_seq ?? selectedCell?.rackSeq ?? selectedCell?.rackId;

    // 현재 선택된 셀과 랙이 일치하는지 확인
    return (
      selectedCell !== null &&
      String(selectedRackSeq) === String(rackSeq) &&
      String(selectedLocationSeq) === String(cellLocationSeq)
    );
  };

  //선택됨:파란색 / 사용 불가: 빨간색 / 사용 중: 초록색 / 비어 있음: 회색

  const getCellClassName = (cell) => {
    if (isSelectedCell(cell)) {
      return ["animate-pulse", "bg-[#3863BA]"].join(" ");
    }

    // const isUnavailable = //
    //   cell.enable_yn === false ||
    //   cell.enable_yn === 0 ||
    //   cell.enable_yn === "N";

    // if (isUnavailable) { //
    //   return "bg-[#C12B2B]";
    // }

    const isUsed = Number(cell.lpn_cnt ?? 0) > 0; 

    if (isUsed) { // 사용 중인 셀은 초록색으로 표시
      return "bg-[#40CB7C]";
    }

    return "bg-[#8F949E]"; // 
  };

  return (
    <div className="flex h-[380px] w-[835px] shrink-0 flex-col overflow-hidden rounded-[10px] gap-[20px] border border-[#DBDBDB] bg-white p-[20px]">
      {/* 랙 이름 및 적재 현황 */}
      <div className="flex h-[50px] shrink-0 items-center justify-between">
        <h2 className="min-w-0 truncate pr-[20px] text-[32px] font-bold text-black">
          {rackData?.rack_name ?? "-"}
        </h2>

        <span className="shrink-0 text-[32px] font-bold text-[#3ECB75]">
          {loadedCellCount}/{Number(rackData?.total_cell ?? cells.length)}
        </span>
      </div>

      {/* 셀 목록 */}
      <div className="overflow-y-auto overflow-x-hidden">
        {cells.length > 0 ? (
          <div className="grid grid-cols-6 content-start gap-[10px]">
            {cells.map((cell, index) => {
              const cellId = cell.location_seq ?? `${rackSeq}-${index}`;

              const cellCode = cell.location_code ?? "-";

              const lpnCount = Number(cell.lpn_cnt ?? 0);

              const totalQty = Number(cell.total_qty ?? 0);

              const isLoading =
                String(loadingCellSeq) ===
                String(cell.location_seq ?? `${rackSeq}-${index}`);

              return (
                <button
                  key={cellId}
                  type="button"
                  onClick={() => onCellClick?.(rackData, cell)}
                  disabled={isLoading}
                  className={[
                    "h-[60px]",
                    "min-w-0",
                    "rounded-[10px]",
                    "transition-all",
                    "duration-200",
                    "disabled:cursor-wait",
                    "disabled:opacity-70",
                    getCellClassName(cell),
                  ].join(" ")}
                  title={
                    `${cellCode} / ` +
                    `LPN ${lpnCount}개 / ` +
                    `수량 ${totalQty}`
                  }
                  aria-label={`${cellCode} 셀 선택`}
                  aria-pressed={isSelectedCell(cell)}
                >
                </button>
              );
            })}
          </div>
        ) : (
          <div className="flex h-full w-full items-center justify-center">
            <span className="text-[26px] font-bold text-[#747983]">
              등록된 셀이 없습니다.
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

export default RackSection;
