import { useEffect, useState } from "react";

import arrow_down_icon from "../../assets/icon/arrow_down_icon.svg";
import rack_detail_icon from "../../assets/icon/rack_detail_icon.svg";

// 백엔드 사용 여부 값을 화면 표시값으로 변환
const getUsageText = (enableYn, isNew = false) => {
  if (enableYn === true || enableYn === 1) {
    return "사용";
  }

  if (enableYn === false || enableYn === 2) {
    return "미사용";
  }

  return isNew ? "사용" : "-";
};

// 비교를 위해 null, undefined, "-" 값을 빈 문자열로 통일
const normalizeValue = (value) => {
  if (value === null || value === undefined || value === "-") {
    return "";
  }

  return String(value).trim();
};

const EMPTY_ZONE_LIST = [];

function RackDetail({
  selectedRack,
  onSaveRack,
  zoneList = EMPTY_ZONE_LIST,
}) {
  const [formData, setFormData] = useState(null);

  const isAdding = selectedRack?.isNew === true;

  // 선택된 랙이 변경되면 상세 정보 초기화
useEffect(() => {
  if (!selectedRack) {
    setFormData(null);
    return;
  }

  setFormData({
    seq: selectedRack.seq ?? null,
    rack_code: selectedRack.isNew ? "" : (selectedRack.rack_code ?? ""),
    rack_name: selectedRack.isNew ? "" : (selectedRack.rack_name ?? ""),
    zone_seq: selectedRack.zone_seq ?? "",
    zone_name: selectedRack.zone_name ?? "",
    rows: selectedRack.isNew ? "" : (selectedRack.rows ?? ""),
    cols: selectedRack.isNew ? "" : (selectedRack.cols ?? ""),
    enable_yn: getUsageText(
      selectedRack.enable_yn,
      selectedRack.isNew,
    ),
    isNew: selectedRack.isNew ?? false,
  });
}, [selectedRack]);

useEffect(() => {
  if (!isAdding || zoneList.length === 0) {
    return;
  }

  setFormData((current) => {
    if (!current) {
      return current;
    }

    if (
      current.zone_seq !== "" &&
      current.zone_seq !== null &&
      current.zone_seq !== undefined
    ) {
      return current;
    }

    const defaultZone = zoneList[0];

    return {
      ...current,
      zone_seq: Number(defaultZone.seq),
      zone_name: defaultZone.zone_name ?? "",
    };
  });
}, [isAdding, zoneList]);

  // 일반 입력값 변경
  const handleFieldChange = (field, value) => {
    setFormData((current) => {
      if (!current) {
        return current;
      }

      return {
        ...current,
        [field]: value,
      };
    });
  };

const handleZoneChange = (event) => {
  const zoneSeq = Number(event.target.value);

  const selectedZone = zoneList.find(
    (zone) => Number(zone.seq) === zoneSeq,
  );

  setFormData((current) => {
    if (!current) return current;

    return {
      ...current,
      zone_seq: zoneSeq,
      zone_name: selectedZone?.zone_name ?? "",
    };
  });
};


  const selectedUsageText = getUsageText(
    selectedRack?.enable_yn,
  );

  // 기존 랙 정보와 현재 입력값 비교
const isChanged =
  normalizeValue(formData?.rack_code) !==
    normalizeValue(selectedRack?.rack_code) ||
  normalizeValue(formData?.rack_name) !==
    normalizeValue(selectedRack?.rack_name) ||
  normalizeValue(formData?.zone_seq) !==
    normalizeValue(selectedRack?.zone_seq) ||
  normalizeValue(formData?.rows) !==
    normalizeValue(selectedRack?.rows) ||
  normalizeValue(formData?.cols) !==
    normalizeValue(selectedRack?.cols) ||
  normalizeValue(formData?.enable_yn) !==
    normalizeValue(selectedUsageText);

  // 필수 입력값 확인
const isRequiredFieldsFilled =
  normalizeValue(formData?.rack_code) !== "" &&
  normalizeValue(formData?.rack_name) !== "" &&
  normalizeValue(formData?.zone_seq) !== "" &&
  normalizeValue(formData?.rows) !== "" &&
  normalizeValue(formData?.cols) !== "" &&
  normalizeValue(formData?.enable_yn) !== "";

  const canSave =
    isRequiredFieldsFilled && (isAdding || isChanged);

  // 랙 정보 저장
 const handleSave = () => {
  if (!canSave || !formData) {
    return;
  }

  const savedRack = {
    ...formData,
    zone_seq: Number(formData.zone_seq),
    rows: Number(formData.rows),
    cols: Number(formData.cols),
    enable_yn: formData.enable_yn === "사용",
    isNew: isAdding,
  };

  onSaveRack?.(savedRack);
};

  if (!selectedRack || !formData) {
    return (
      <div className="flex h-full w-full flex-col items-center justify-center gap-[50px] px-[50px]">
        <div className="flex h-[250px] w-[250px] items-center justify-center">
          <img
            src={rack_detail_icon}
            alt="선택된 랙 없음"
            className="h-[229.65px] w-[230px] object-contain"
          />
        </div>

        <span className="w-full text-center text-[36px] font-extrabold text-[#243659]">
          관리하실 랙을 선택해 주세요.
        </span>
      </div>
    );
  }

  return (
    <div className="flex h-full w-[535px] flex-1 flex-col gap-[30px] px-[50px] py-[30px]">
      {/* 상세 정보 헤더 */}
      <div className="flex h-[50px] w-[535px] items-center justify-center gap-[10px]">
        <div className="flex h-[45px] w-[348px] items-center">
          <span className="text-[36px] font-extrabold text-[#243659]">
            {isAdding ? "랙 추가" : "상세 정보"}
          </span>
        </div>

        <button
          type="button"
          onClick={handleSave}
          disabled={!canSave}
          className={`flex h-[50px] w-[177px] items-center justify-center rounded-[10px] px-[20px] text-[22px] font-semibold ${
            canSave
              ? "cursor-pointer bg-[#40CB7C] text-white"
              : "cursor-not-allowed bg-[#A8ADB5] text-[#EBEDF1]"
          }`}
        >
          변경 사항 저장
        </button>
      </div>

      <div className="h-[2px] w-[535px] shrink-0 bg-white" />

      {/* 랙 상세 정보 입력 영역 */}
      <div className="flex w-[535px] flex-col justify-center gap-[20px]">
        <DetailRow
          label="랙 코드"
          fieldName="rack_code"
          value={formData.rack_code}
          editable
          onChange={(event) =>
            handleFieldChange(
              "rack_code",
              event.target.value,
            )
          }
        />

        <DetailRow
          label="랙 이름"
          fieldName="rack_name"
          value={formData.rack_name}
          editable
          onChange={(event) =>
            handleFieldChange(
              "rack_name",
              event.target.value,
            )
          }
        />

        <DetailRow
  label="구역 정보"
  fieldName="zone_seq"
  value={formData.zone_seq}
  editable
  type="select"
  options={zoneList}
  onChange={handleZoneChange}
/>

        <DetailRow
          label="가로"
          fieldName="cols"
          value={formData.cols}
          editable
          numeric
          onChange={(event) =>
            handleFieldChange(
              "cols",
              event.target.value,
            )
          }
        />

        <DetailRow
          label="세로"
          fieldName="rows"
          value={formData.rows}
          editable
          numeric
          onChange={(event) =>
            handleFieldChange(
              "rows",
              event.target.value,
            )
          }
        />

        <DetailRow
          label="사용여부"
          fieldName="enable_yn"
          value={formData.enable_yn}
          editable
          type="select"
          options={["사용", "미사용"]}
          onChange={(event) =>
            handleFieldChange(
              "enable_yn",
              event.target.value,
            )
          }
        />
      </div>
    </div>
  );
}

function DetailRow({
  label,
  fieldName,
  value,
  editable = false,
  numeric = false,
  type = "text",
  options = [],
  onChange,
}) {
  const inputId = `rack-${fieldName}`;

  const handleInputChange = (event) => {
    if (numeric) {
      event.target.value = event.target.value.replace(
        /[^0-9]/g,
        "",
      );
    }

    onChange?.(event);
  };

  return (
  <div className="grid w-full grid-cols-[130px_1fr] items-center gap-[20px]">
    <label
      htmlFor={inputId}
      className="text-[28px] font-bold text-[#243659]"
    >
      {label}
    </label>

    {type === "select" ? (
      <div className="relative ml-auto w-[305px]">
        <select
          id={inputId}
          name={fieldName}
          value={value === "-" ? "" : (value ?? "")}
          disabled={!editable}
          onChange={onChange}
          className={`h-[50px] w-full appearance-none rounded-[10px] border-none bg-white pl-[45px] pr-[55px] text-center text-[24px] font-normal leading-[50px] text-black outline-none ${
            editable
              ? "cursor-pointer"
              : "cursor-default opacity-100"
          }`}
        >

          {options.map((option) => {
            const isObjectOption =
              typeof option === "object" && option !== null;

            const optionValue = isObjectOption
              ? option.seq
              : option;

            const optionLabel = isObjectOption
              ? option.zone_name
              : option;

            return (
              <option
                key={optionValue}
                value={optionValue}
                className="bg-white text-center text-[24px] text-black"
              >
                {optionLabel}
              </option>
            );
          })}
        </select>

        <img
          src={arrow_down_icon}
          alt=""
          aria-hidden="true"
          className="pointer-events-none absolute right-[20px] top-1/2 h-[12.46px] w-[21.2px] -translate-y-1/2"
        />
      </div>
    ) : (
      <input
        id={inputId}
        name={fieldName}
        type="text"
        inputMode={numeric ? "numeric" : undefined}
        pattern={numeric ? "[0-9]*" : undefined}
        value={value === "-" ? "" : (value ?? "")}
        placeholder={
          !editable && normalizeValue(value) === "" ? "-" : ""
        }
        readOnly={!editable}
        onChange={handleInputChange}
        className={`ml-auto h-[50px] w-[305px] rounded-[10px] border-none bg-white px-[15px] text-center text-[24px] font-normal text-black outline-none ${
          editable ? "cursor-text" : "cursor-default"
        }`}
      />
    )}
  </div>
);
}

export default RackDetail;