// 모니터링 센서 연결 상태
const monitoringSensor = [
  { name: "ACS #01", status: true },
  { name: "MES", status: false },
  { name: "QR PC", status: false },
  { name: "MASTER PLC", status: true },
];

// 센서 연결 상태 표시
function SensorStatus() {
  return (
    <div className="grid h-full w-[440px] grid-cols-2 items-center gap-x-[20px] px-[10px]">
      {monitoringSensor.map((sensor) => (
        <div
          key={sensor.name}
          className="flex h-[40px] min-w-0 items-center gap-[10px]"
        >
          {/* 연결 상태 표시 */}
          <div
            className={`h-[20px] w-[20px] shrink-0 rounded-full ${
              sensor.status ? "bg-[#45BE3F]" : "bg-[#D9D9D9]"
            }`}
          />

          {/* 센서 이름 */}
          <span className="whitespace-nowrap text-[20px] font-normal text-black">
            {sensor.name}
          </span>
        </div>
      ))}
    </div>
  );
}

export default SensorStatus;