import { useEffect, useState } from "react";
import x_icon from "../../assets/icon/x_Icon.svg";

function PickingDetailModal({
  isOpen,
  modalType = "detail",
  data = {},
  onClose = () => {},
  onSave = () => {},
  onUpdateSubMaterials = () => {},
  onConfirmPublish = () => {},
  onConfirmQuantities = () => {},
  onConfirmPartition = () => {},
  onConfirmMerge = () => {},
}) {
  const [selectedWashType, setSelectedWashType] = useState("W");

  useEffect(() => {
    if (isOpen && modalType === "detail") {
      setSelectedWashType("W");
    }
  }, [isOpen, modalType]);

  if (!isOpen) {
    return null;
  }

  // 피킹 리스트 신규등록
  if (modalType === "create") {
    return <PickingCreateModal onClose={onClose} onSave={onSave} />;
  }

  // 하위 자재 상세
  if (modalType === "detail") {
    return (
      <MaterialDetailModal
        data={data}
        selectedWashType={selectedWashType}
        setSelectedWashType={setSelectedWashType}
        onClose={onClose}
        onApply={onUpdateSubMaterials}
      />
    );
  }

  // 발행 확인
  if (modalType === "publish") {
    return (
      <PublishConfirmModal
        data={data}
        onClose={onClose}
        onConfirm={onConfirmPublish}
      />
    );
  }

  // 분할 수량 지정
  if (modalType === "partitionQuantity") {
    return (
      <PartitionQuantityModal
        data={data}
        onClose={onClose}
        onConfirm={onConfirmQuantities}
      />
    );
  }

  // 분할 확인
  if (modalType === "partitionConfirm") {
    return (
      <PartitionConfirmModal
        data={data}
        onClose={onClose}
        onConfirm={onConfirmPartition}
      />
    );
  }

  // 통합 확인
  if (modalType === "mergeConfirm") {
    return (
      <MergeConfirmModal
        data={data}
        onClose={onClose}
        onConfirm={onConfirmMerge}
      />
    );
  }

  return null;
}

const EMPTY_PICKING_FORM = {
  engine_no: "",
  mes_seq_no: "",
  proc_code: "",
  order_no: "",
  created_at: "",
  remarks: "",
};

