function PickingCreateModal({ onClose, onSave }) {
  const [formData, setFormData] = useState({
    ...EMPTY_PICKING_FORM,
  });

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((previousData) => ({
      ...previousData,
      [name]: value,
    }));
  };

  const validateForm = () => {
    if (!formData.engine_no.trim()) {
      window.alert("호기를 입력해 주세요.");
      return false;
    }

    if (!formData.mes_seq_no.trim()) {
      window.alert("서열을 입력해 주세요.");
      return false;
    }

    if (!formData.proc_code.trim()) {
      window.alert("공정을 입력해 주세요.");
      return false;
    }

    if (!formData.order_no.trim()) {
      window.alert("지시 번호를 입력해 주세요.");
      return false;
    }

    if (!formData.created_at.trim()) {
      window.alert("예정일을 선택해 주세요.");
      return false;
    }

    return true;
  };

  const handleSubmit = () => {
    if (!validateForm()) {
      return;
    }

    onSave({
      ...formData,
      publish_yn: "N",
    });
  };

  return (
    <ModalBackground onClose={onClose}>
      <div className="flex h-[720px] w-[580px] flex-col gap-[30px] rounded-[20px] bg-white p-[30px]">
        {/* 헤더 */}
        <div className="relative flex h-[50px] w-[520px] items-center justify-center">
          <h2 className="text-center text-[40px] font-extrabold text-black">
            피킹 리스트 추가
          </h2>

          <button
            type="button"
            onClick={onClose}
            className="absolute right-0 flex h-[37px] w-[37px] items-center justify-center"
            aria-label="피킹 리스트 신규등록 닫기"
          >
            <img src={x_icon} alt="" className="h-[18.5px] w-[18.5px]" />
          </button>
        </div>

        {/* 입력 영역 */}
        <div className="flex h-[480px] w-[520px] flex-col gap-[15px] rounded-[20px] p-[20px] border border-[#DFDFDF]">
          <PickingFormRow label="호기" htmlFor="engine_no">
            <input
              id="engine_no"
              name="engine_no"
              type="text"
              value={formData.engine_no}
              onChange={handleChange}
              placeholder="호기 입력"
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] text-center text-[24px] font-normal outline-none"
            />
          </PickingFormRow>

          <PickingFormRow label="공정" htmlFor="proc_code">
            <input
              id="proc_code"
              name="proc_code"
              type="text"
              value={formData.proc_code}
              onChange={handleChange}
              placeholder="공정 입력"
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] text-center text-[24px] font-normal outline-none"
            />
          </PickingFormRow>

          <PickingFormRow label="서열" htmlFor="mes_seq_no">
            <input
              id="mes_seq_no"
              name="mes_seq_no"
              type="text"
              value={formData.mes_seq_no}
              onChange={handleChange}
              placeholder="서열 입력"
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] text-center text-[24px] font-normal outline-none"
            />
          </PickingFormRow>

          <PickingFormRow label="지시 번호" htmlFor="order_no">
            <input
              id="order_no"
              name="order_no"
              type="text"
              value={formData.order_no}
              onChange={handleChange}
              placeholder="지시 번호 입력"
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1]  text-center text-[24px] font-normal outline-none"
            />
          </PickingFormRow>

          <PickingFormRow label="예정일" htmlFor="created_at">
            <input
              id="created_at"
              name="created_at"
              type="date"
              value={formData.created_at}
              onChange={handleChange}
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] px-[15px] text-center text-[24px] font-normal outline-none"
            />
          </PickingFormRow>

          <PickingFormRow label="K_LPN" htmlFor="K_LPN">
            <input
              id="K_LPN"
              name="K_LPN"
              type="text"
              value={formData.K_LPN}
              onChange={handleChange}
              placeholder="K_LPN 입력"
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] text-center text-[24px] font-normal outline-none"
            />
          </PickingFormRow>
          <PickingFormRow label="사용 여부" htmlFor="use_yn">
            <input
              id="use_yn"
              name="use_yn"
              type="text"
              value={formData.use_yn}
              onChange={handleChange}
              placeholder="사용 여부 입력"
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] text-center text-[24px] font-normal outline-none"
            />
          </PickingFormRow>
        </div>

        {/* 버튼 */}
        <div className="flex h-[70px] w-[520px] gap-[30px]">
          <button
            type="button"
            onClick={onClose}
            className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#8F949E]/90 text-[32px] font-extrabold text-white"
          >
            변경 취소
          </button>

          <button
            type="button"
            onClick={handleSubmit}
            className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#243659]/90 text-[32px] font-extrabold text-white"
          >
            변경 사항 저장
          </button>
        </div>
      </div>
    </ModalBackground>
  );
}
function PickingFormRow({ label, htmlFor, children }) {
  return (
    <div className="flex h-[50px] w-[480px] items-center justify-between">
      <label
        htmlFor={htmlFor}
        className="flex h-[30px] w-[160px] items-center text-[24px] font-normal text-black"
      >
        {label}
      </label>

      {children}
    </div>
  );
}
function MaterialDetailModal({
  data,
  selectedWashType,
  setSelectedWashType,
  onClose,
  onApply,
}) {
  // 신규등록으로 생성된 행에서만 추가/수정 가능
  const isEditable = data.isNew === true;

  const [subMaterialList, setSubMaterialList] = useState([]);
  const [draftMaterial, setDraftMaterial] = useState(null);

  useEffect(() => {
    let nextList = [];

    if (Array.isArray(data.sub_material_list)) {
      nextList = data.sub_material_list;
    } else if (!isEditable) {
      nextList = defaultSubMaterialList;
    }

    setSubMaterialList(nextList);
    setDraftMaterial(null);
  }, [data, isEditable]);

  const filteredMaterials = subMaterialList.filter(
    (item) => item.wash_yn === selectedWashType,
  );

  // 점선 플러스 클릭
  const handleAddMaterial = () => {
    if (!isEditable || draftMaterial) {
      return;
    }

    setDraftMaterial({
      item_code: "",
      quantity: "",
      wash_yn: selectedWashType,
    });
  };

  // 신규 하위 자재 입력값 변경
  const handleDraftChange = (event) => {
    const { name, value } = event.target;

    const nextValue =
      name === "quantity" ? value.replace(/[^0-9]/g, "") : value;

    setDraftMaterial((previous) => ({
      ...previous,
      [name]: nextValue,
      wash_yn: selectedWashType,
    }));
  };

  // 입력 행을 실제 목록에 추가
  const handleCommitDraft = () => {
    if (!draftMaterial) {
      return;
    }

    const itemCode = draftMaterial.item_code.trim();
    const quantity = Number(draftMaterial.quantity);

    // 아직 모든 항목을 입력하지 않았다면 확정하지 않음
    if (!itemCode || quantity <= 0) { 
      return;
    }

    const newSubMaterial = {
      seq: Date.now(),
      item_code: itemCode,
      quantity,
      wash_yn: selectedWashType,
    };

    setSubMaterialList((previous) => [...previous, newSubMaterial]);

    setDraftMaterial(null);
  };

  // Enter 입력 시 행 확정
  const handleDraftKeyDown = (event) => {
    if (event.key !== "Enter") {
      return;
    }

    event.preventDefault();
    handleCommitDraft();
  };

  // 변경사항 적용
  const handleApplyChanges = () => {
    if (draftMaterial) {
      const itemCode = draftMaterial.item_code.trim();
      const quantity = Number(draftMaterial.quantity);

      if (!itemCode || quantity <= 0) {
        window.alert("자재 코드, 자재 수량을 모두 입력해 주세요.");
        return;
      }

      const completedList = [
        ...subMaterialList,
        {
          seq: Date.now(),
          item_code: itemCode,
          quantity,
          wash_yn: selectedWashType,
        },
      ];

      onApply(data.id, completedList);
      onClose();
      return;
    }

    onApply(data.id, subMaterialList);
    onClose();
  };

  return (
    <ModalBackground onClose={onClose}>
      <div className="relative flex min-h-[525px] w-[920px] flex-col items-center gap-[30px] rounded-[20px] bg-white p-[30px]">
        {/* 헤더 */}
        <div className="relative flex h-[50px] w-[640px] items-center justify-center">
          <h2 className="text-center text-[40px] font-extrabold text-black">
            하위 자재 상세 목록
          </h2>
        </div>

        <button
          type="button"
          onClick={onClose}
          className="absolute right-10 top-[30px] flex h-[37px] w-[37px] items-center justify-center"
          aria-label="하위 자재 상세 목록 닫기"
        >
          <img src={x_icon} alt="" className="h-[18.5px] w-[18.5px]" />
        </button>

        {/* 내용 */}
        <div className="flex min-h-[235px] w-full flex-col gap-[10px]">
          <div className="flex h-[25px] w-[850px] items-center justify-end text-[20px] text-[#9A9FA8]">
            생성 일자 : {data.created_at || "-"}
          </div>

          <div className="flex min-h-[200px] w-full gap-[20px] rounded-[20px]">
            {/* 세척 여부 */}
            <div className="flex min-h-[200px] w-[240px] flex-col items-center gap-[15px] overflow-hidden rounded-[20px] border border-[#DFDFDF] p-[20px]">
              <div className="flex h-[30px] w-[180px] shrink-0 justify-center text-[24px] font-normal text-black">
                세척 여부
              </div>

              <button
                type="button"
                onClick={() => {
                  setSelectedWashType("W");
                  setDraftMaterial(null);
                }}
                className={`flex h-[50px] w-[200px] shrink-0 items-center justify-center rounded-[10px] text-[22px] font-semibold ${
                  selectedWashType === "W"
                    ? "bg-[#243659] text-white"
                    : "bg-[#EBEDF1] text-black"
                }`}
              >
                세척 자재
              </button>

              <button
                type="button"
                onClick={() => {
                  setSelectedWashType("N");
                  setDraftMaterial(null);
                }}
                className={`flex h-[50px] w-[200px] shrink-0 items-center justify-center rounded-[10px] text-[22px] font-semibold ${
                  selectedWashType === "N"
                    ? "bg-[#243659] text-white"
                    : "bg-[#EBEDF1] text-black"
                }`}
              >
                비세척 자재
              </button>

              <div className="flex-1 bg-white" />
            </div>

            {/* 하위 자재 목록 */}
            <div className="flex min-h-[200px] w-[640px] flex-col rounded-[20px] border border-[#E8E8E8] p-[20px]">
              <div className="flex min-h-[200px] flex-col overflow-hidden rounded-[10px] border border-[#E8E8E8]">
                {/* 테이블 헤더 */}
                <div className="grid h-[50px] shrink-0 grid-cols-[95px_232.5px_232.5px] items-center bg-[#EBEDF1]">
                  <div className="text-center text-[22px] font-bold text-[#202020]">
                    순번
                  </div>

                  <div className="text-center text-[22px] font-bold text-[#202020]">
                    자재 코드
                  </div>

                  <div className="text-center text-[22px] font-bold text-[#202020]">
                    자재 수량
                  </div>
                </div>

                {/* 테이블 데이터 */}
                <div className="hide-scrollbar flex min-h-0 flex-1 flex-col overflow-y-auto bg-white p-[10px]">
                  {filteredMaterials.map((item, index) => (
                    <div
                      key={`${item.wash_yn}-${item.seq}`}
                      className="grid h-[50px] shrink-0 grid-cols-[95px_232.5px_232.5px] items-center"
                    >
                      <div className="text-center text-[22px] text-[#202020]">
                        {index + 1}
                      </div>

                      <div className="truncate text-center text-[22px] text-[#202020]">
                        {item.item_code || "-"}
                      </div>

                      <div className="text-center text-[22px] text-[#202020]">
                        {item.quantity || "-"}
                      </div>

                    </div>
                  ))}

                  {/* 신규 입력 행 */}
                  {draftMaterial && (
                    <div className="grid h-[50px] shrink-0 grid-cols-[95px_232.5px_232.5px] items-center gap-0">
                      <div className="flex items-center justify-center">
                        <div className="flex h-[40px] w-[75px] items-center justify-center p-[10px] rounded-[10px] bg-[#EBEDF1] text-[24px] text-black">
                          {filteredMaterials.length + 1}
                        </div>
                      </div>

                      <div className="flex items-center justify-center ">
                        <input
                          name="item_code"
                          type="text"
                          value={draftMaterial.item_code}
                          onChange={handleDraftChange}
                          onKeyDown={handleDraftKeyDown}
                          placeholder="-"
                          autoFocus
                          className="h-[40px] w-[215px] rounded-[10px] bg-[#EBEDF1] p-[10px] font-normal text-center text-[24px] outline-none"
                        />
                      </div>

                      <div className="flex items-center justify-center">
                        <input
                          name="quantity"
                          type="text"
                          inputMode="numeric"
                          value={draftMaterial.quantity}
                          onChange={handleDraftChange}
                          onKeyDown={handleDraftKeyDown}
                          placeholder="-"
                          className="h-[40px] w-[215px] rounded-[10px] bg-[#EBEDF1] p-[10px] font-normal text-center text-[24px] outline-none"
                        />
                      </div>
                    </div>
                  )}

                  {/* 추가 버튼 */}
                  {isEditable && !draftMaterial && (
                    <button
                      type="button"
                      onClick={handleAddMaterial}
                      className="mt-[10px] flex min-h-[80px] w-full shrink-0 items-center justify-center rounded-[20px] border border-dashed border-[#A8ADB5] text-[28px] font-normal text-[#9A9FA8]"
                      aria-label="하위 자재 추가"
                    >
                      +
                    </button>
                  )}

                  {/* 기존 행이며 자재가 없는 경우 */}
                  {!isEditable && filteredMaterials.length === 0 && (
                    <div className="flex min-h-[120px] flex-1 items-center justify-center text-[24px] font-semibold text-[#9A9FA8]">
                      하위 자재가 없습니다.
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* 하단 버튼 */}
        {isEditable && (
          <div className="flex h-[70px] w-full gap-[30px]">
            <button
              type="button"
              onClick={onClose}
              className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#8F949E] text-[32px] font-extrabold text-white"
            >
              변경 취소
            </button>

            <button
              type="button"
              onClick={handleApplyChanges}
              className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#243659] text-[32px] font-extrabold text-white"
            >
              변경 사항 적용
            </button>
          </div>
        )}
      </div>
    </ModalBackground>
  );
}

function PublishConfirmModal({ data, onClose, onConfirm }) {
  return (
    <ModalBackground onClose={onClose}>
      <div className="flex min-h-[485px] w-[700px] flex-col gap-[30px] rounded-[20px] bg-white p-[30px]">
        {/* 헤더 */}
        <div className="relative flex h-[50px] w-[640px] items-center justify-center ">
          <h2 className="text-center text-[40px] font-extrabold text-black">
            피킹 리스트 발행 확정
          </h2>

          <button
            type="button"
            onClick={onClose}
            className="absolute right-0 top-0 flex h-[37px] w-[37px] items-center justify-center"
            aria-label="피킹 리스트 발행 확정 닫기"
          >
            <img src={x_icon} alt="" className="h-[18px] w-[18px]" />
          </button>
        </div>

        {/* 발행 정보 */}
        <div className="flex h-[245px] flex-1 flex-col items-center justify-center gap-[30px]">
          <p className="text-center text-[28px] font-normal text-black">
            선택된 피킹리스트의 발행을 확정합니다.
          </p>

          <div className="flex flex-col items-center gap-[2px]">
            <span className="text-[28px] font-extrabold text-[#243659]">
              [피킹 리스트]
            </span>

            <span className="text-[28px] font-normal text-black">
              {data.order_no || "-"}
            </span>
          </div>

          <div className="flex flex-col items-center gap-[2px]">
            <span className="text-[28px] font-extrabold text-[#243659]">
              [착수(예정)일]
            </span>

            <span className="text-[28px] font-normal text-black">
              {data.start_date || data.delivery_seq || "-"}
            </span>
          </div>
        </div>

        {/* 버튼 */}
        <div className="flex h-[70px] w-full gap-[30px]">
          <button
            type="button"
            onClick={onClose}
            className="flex h-full flex-1 items-center justify-center gap-[10px] rounded-[10px] bg-[#8F949E]/90 text-[32px] font-extrabold text-white"
          >
            발행 취소
          </button>

          <button
            type="button"
            onClick={() => onConfirm(data)}
            className="flex h-full flex-1 items-center justify-center gap-[10px] rounded-[10px] bg-[#243659]/90 text-[32px] font-extrabold text-white"
          >
            발행 확정
          </button>
        </div>
      </div>
    </ModalBackground>
  );
}

function PartitionQuantityModal({ data, onClose, onConfirm }) {
  // 선택한 각 자재의 이동 수량을 item id 기준으로 관리
  const [quantities, setQuantities] = useState({});

  useEffect(() => {
    const initialQuantities = {};

    (data.items ?? []).forEach((item) => {
      // 처음에는 전체 수량을 기본값으로 보여줌
      initialQuantities[item.id] = item.quantity ?? 0;
    });

    setQuantities(initialQuantities);
  }, [data]);

  // 숫자만 입력되도록 처리하고 원본 수량보다 큰 값은 제한
  const handleQuantityChange = (item, value) => {
    const numericValue = value.replace(/[^0-9]/g, "");
    const nextQuantity =
      numericValue === ""
        ? ""
        : Math.min(Number(numericValue), Number(item.quantity ?? 0));

    setQuantities((previous) => ({
      ...previous,
      [item.id]: nextQuantity,
    }));
  };

  const handleConfirm = () => {
    const quantityList = (data.items ?? []).map((item) => ({
      id: item.id,
      quantity: Number(quantities[item.id] ?? 0),
    }));

    // 0 이하이거나 원본 수량을 초과하는 값이 있으면 진행하지 않음
    const sourceItems = new Map(
      (data.items ?? []).map((item) => [item.id, item]),
    );

    const hasInvalidQuantity = quantityList.some((entry) => {
      const originalQuantity = Number(sourceItems.get(entry.id)?.quantity ?? 0);

      return entry.quantity <= 0 || entry.quantity > originalQuantity;
    });

    if (hasInvalidQuantity) {
      window.alert("이동 수량은 1 이상이며 현재 수량 이하여야 합니다.");
      return;
    }

    onConfirm(quantityList);
  };

  return (
    <ModalBackground onClose={onClose}>
      <div className="flex w-[580px] flex-col gap-[30px] rounded-[20px] bg-white p-[30px]">
        <div className="relative flex h-[50px] w-[520px] items-center justify-center">
          <h2 className="text-center text-[40px] font-extrabold text-black">
            분할 수량 지정
          </h2>

          <button
            type="button"
            onClick={onClose}
            className="absolute right-0 top-1/2 flex h-[37px] w-[37px] -translate-y-1/2 items-center justify-center"
            aria-label="분할 수량 지정 닫기"
          >
            <img src={x_icon} alt="" className="h-[18px] w-[18px]" />
          </button>
        </div>

        <div className="flex w-[520px] flex-col gap-[15px] overflow-y-auto rounded-[20px] border border-[#DFDFDF] p-[20px]">
          {(data.items ?? []).map((item) => (
            <div
              key={item.id}
              className="grid h-[55px] grid-cols-[180px_1fr] items-center gap-[20px]"
            >
              <span className="truncate text-[24px] font-normal  text-black">
                {item.item_code || "-"}
              </span>

              <input
                type="text"
                inputMode="numeric"
                value={quantities[item.id] ?? ""}
                onChange={(event) =>
                  handleQuantityChange(item, event.target.value)
                }
                className="h-[50px] rounded-[10px] border-none bg-[#EBEDF1] text-center text-[24px] text-black outline-none"
                aria-label={`${item.item_code} 이동 수량`}
              />
            </div>
          ))}
        </div>

        <div className="flex h-[70px] w-full gap-[30px]">
          <button
            type="button"
            onClick={onClose}
            className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#8F949E]/90 text-[32px] font-extrabold text-white"
          >
            지정 취소
          </button>

          <button
            type="button"
            onClick={handleConfirm}
            className="flex h-full flex-1 items-center justify-center rounded-[10px] bg-[#243659]/90 text-[32px] font-extrabold text-white"
          >
            지정 확인
          </button>
        </div>
      </div>
    </ModalBackground>
  );
}

