import { useState } from "react";
import x_icon from "../../assets/icon/x_Icon.svg";

function LpnModal({ data, onClose }) {
  const integratedMaterials = data?.items ?? [];

  // 자재가 2개 이상이면 통합보관으로 간주
  const isIntegrated = integratedMaterials.length > 1;

  const detailList = [
    { label: "자재 코드", value: data?.items?.[0]?.item_code ?? "-" },
    { label: "자재명", value: data?.items?.[0]?.item_name ?? "-" },
    {
      label: "등록일",
      value: data?.txn_date?.replace("T", " ").slice(0, 19) ?? "-",
    },
    {
      label: "입고일",
      value: data?.txn_date?.replace("T", " ").slice(0, 19) ?? "-",
    },
    { label: "수량", value: data?.total_qty ?? "-" },
    { label: "적재 위치", value: data?.location_code ?? "-" },
    {
      label: "세척 여부",
      value: data?.items?.every((item) => item.washing_yn) ? "Y" : "N",
    },
    {
      label: "통합 보관",
      value: (data?.items?.length ?? 0) > 1 ? "Y" : "N",
    },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30">
      <div className="flex h-[600px] w-[900px] flex-col rounded-[20px] bg-white p-[30px]">
        {/* 모달 헤더 */}
        <div className="relative h-[50px] w-full">
          <h2 className="absolute inset-0 flex items-center justify-center whitespace-nowrap text-[40px] font-extrabold">
            {data?.lpn_code ?? "-"}
          </h2>

          <button
            type="button"
            onClick={onClose}
            aria-label="모달 닫기"
            className="absolute right-0 top-1/2 flex h-[37px] w-[37px] -translate-y-1/2 items-center justify-center"
          >
            <img
              src={x_icon}
              alt=""
              aria-hidden="true"
              className="h-[18.5px] w-[18.5px]"
            />
          </button>
        </div>

        {/* 상세 정보 영역 */}
        <div className="flex h-[475px] w-full flex-col gap-[10px]">
          <div className="flex h-[25px] w-full justify-end text-[20px] text-[#9A9FA8]">
            발행 일자 : {data?.txn_date?.replace("T", " ").slice(0, 19) ?? "-"}
          </div>

          <div className="flex h-[440px] w-full gap-[15px] rounded-[20px] border border-[#DFDFDF] p-[20px]">
            {/* LPN 기본 정보 */}
            <div
              className={`flex h-full flex-col overflow-hidden rounded-[10px] border border-[#D9DDE5] ${
                integratedMaterials.length > 1 ? "w-[400px]" : "flex-1"
              }`}
            >
              {detailList.map((item, index) => (
                <div
                  key={`${item.label}-${index}`}
                  className="grid min-h-0 flex-1 grid-cols-[150px_1fr] border-b border-[#D9DDE5] last:border-b-0"
                >
                  <div className="flex items-center justify-center bg-[#E9ECF2] text-[22px] font-semibold text-[#243659]">
                    {item.label}
                  </div>

                  <div className="flex items-center justify-center bg-white text-[22px] font-normal text-black">
                    {item.value}
                  </div>
                </div>
              ))}
            </div>

            {/* 통합 보관 자재 목록 */}
            {isIntegrated && (
              <div className="flex h-[400px] w-[400px] flex-col items-center gap-[20px] rounded-[10px] bg-[#EBEDF1] p-[20px]">
                <div className="flex h-[27px] w-[200px] items-center justify-center text-center text-[22px] font-bold text-[#243659]">
                  통합 보관 자재 목록
                </div>
                <div className="flex h-[313px] w-[320px] flex-col items-center gap-[10px] overflow-y-auto">
                  {" "}
                  {integratedMaterials.length > 0 ? (
                    integratedMaterials.map((material) => (
                      <div
                        key={material.txn_seq}
                        className="flex h-[42px] w-[300px] shrink-0 items-center justify-between rounded-[10px] bg-white px-[15px] text-[22px]"
                      >
                        <div className="flex h-[25px] w-[220px] items-center justify-center">

                          {material.item_code}
                        </div>
                        <div className="flex h-[25px] w-[100px] items-center justify-center">

                          {material.qty} {material.uom}
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="flex h-full items-center justify-center text-[18px] text-[#9A9FA8]">

                      통합 보관 자재가 없습니다.
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default LpnModal;
