import { useEffect, useState } from "react";

import arrow_down_icon from "../../assets/icon/arrow_down_icon.svg";
import x_icon from "../../assets/icon/x_Icon.svg";

const EMPTY_FORM = {
  item_code: "",
  item_name: "",
  uom: "",
  washing_yn: "",
  mixed_allow: "",
  kitting_grp: "",
  use_yn: "",
};

// select의 문자열 값을 boolean으로 변환
const convertSelectValue = (value) => {
  if (value === "true") {
    return true;
  }

  if (value === "false") {
    return false;
  }

  return value;
};

function MaterialDetailModal({
  material,
  mode,
  onClose,
  onSave,
  onUpdate,
}) {
  const [formData, setFormData] = useState(EMPTY_FORM);

  const isCreateMode = mode === "create";

  // 모달 모드 또는 선택 자재가 변경되면 입력값 초기화
  useEffect(() => {
    if (isCreateMode) {
      setFormData({ ...EMPTY_FORM });
      return;
    }

    if (!material) {
      return;
    }

    setFormData({
      item_code: material.item_code ?? "",
      item_name: material.item_name ?? "",
      uom: material.uom ?? "",
      washing_yn: material.washing_yn ?? "",
      mixed_allow: material.mixed_allow ?? "",
      kitting_grp: material.kitting_grp ?? "",
      use_yn: material.use_yn ?? "",
    });
  }, [material, isCreateMode]);

  // 입력값 변경
  const handleChange = (event) => {
    const { name, value } = event.target;
    const convertedValue = convertSelectValue(value);

    setFormData((currentData) => {
      // 혼적을 허용하지 않으면 키팅 그룹 초기화
      if (name === "mixed_allow" && convertedValue === false) {
        return {
          ...currentData,
          mixed_allow: false,
          kitting_grp: "",
        };
      }

      return {
        ...currentData,
        [name]: convertedValue,
      };
    });
  };

  // 입력값 검증
  const validateForm = () => {
    const requiredFields = [
      {
        isInvalid: !formData.item_code.trim(),
        message: "자재 코드를 입력해 주세요.",
      },
      {
        isInvalid: !formData.item_name.trim(),
        message: "자재명을 입력해 주세요.",
      },
      {
        isInvalid: !formData.uom.trim(),
        message: "단위를 입력해 주세요.",
      },
      {
        isInvalid: formData.washing_yn === "",
        message: "세척 여부를 선택해 주세요.",
      },
      {
        isInvalid: formData.mixed_allow === "",
        message: "혼적 허용 여부를 선택해 주세요.",
      },
      {
        isInvalid: formData.use_yn === "",
        message: "사용 여부를 선택해 주세요.",
      },
    ];

    const invalidField = requiredFields.find(
      ({ isInvalid }) => isInvalid,
    );

    if (invalidField) {
      alert(invalidField.message);
      return false;
    }

    return true;
  };

  // 자재 등록 또는 수정
  const handleSubmit = () => {
    if (!validateForm()) {
      return;
    }

    if (isCreateMode) {
      onSave?.(formData);
      return;
    }

    onUpdate?.({
      seq: material.seq,
      ...formData,
    });
  };

  if (!mode || (!isCreateMode && !material)) {
    return null;
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        className="flex h-[720px] w-[580px] flex-col gap-[30px] rounded-[15px] bg-white p-[30px]"
        onClick={(event) => event.stopPropagation()}
      >
        {/* 모달 헤더 */}
        <div className="relative flex h-[50px] items-center justify-center">
          <h2 className="text-[40px] font-extrabold text-[#222222]">
            {isCreateMode ? "자재 신규등록" : "자재 관리"}
          </h2>

          <button
            type="button"
            onClick={onClose}
            aria-label="모달 닫기"
            className="absolute right-0 flex h-[37px] w-[37px] items-center justify-center"
          >
            <img
              src={x_icon}
              alt=""
              aria-hidden="true"
              className="h-[18.5px] w-[18.5px]"
            />
          </button>
        </div>

        {/* 자재 정보 입력 영역 */}
        <div className="flex h-[480px] w-[520px] flex-col gap-[15px] rounded-[20px] border border-[#DFDFDF] p-[20px]">
          <FormRow label="자재 코드" htmlFor="item_code">
            <input
              id="item_code"
              name="item_code"
              type="text"
              value={formData.item_code}
              onChange={handleChange}
              readOnly={!isCreateMode}
              placeholder="자재 코드 입력"
              className={`h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] px-[15px] text-center text-[24px] font-normal outline-none ${
                isCreateMode
                  ? "cursor-text"
                  : "cursor-not-allowed"
              }`}
            />
          </FormRow>

          <FormRow label="자재명" htmlFor="item_name">
            <input
              id="item_name"
              name="item_name"
              type="text"
              value={formData.item_name}
              onChange={handleChange}
              readOnly={!isCreateMode}
              placeholder="자재명 입력"
              className={`h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] px-[15px] text-center text-[24px] font-normal outline-none ${
                isCreateMode
                  ? "cursor-text"
                  : "cursor-not-allowed"
              }`}
            />
          </FormRow>

          <FormRow label="단위" htmlFor="uom">
            <input
              id="uom"
              name="uom"
              type="text"
              value={formData.uom}
              onChange={handleChange}
              placeholder="단위 입력"
              className="h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] px-[15px] text-center text-[24px] font-normal outline-none"
            />
          </FormRow>

          <FormRow label="세척 여부" htmlFor="washing_yn">
            <YnSelect
              name="washing_yn"
              value={formData.washing_yn}
              onChange={handleChange}
            />
          </FormRow>

          <FormRow label="혼적 허용" htmlFor="mixed_allow">
            <YnSelect
              name="mixed_allow"
              value={formData.mixed_allow}
              onChange={handleChange}
            />
          </FormRow>

          <FormRow label="키팅 그룹" htmlFor="kitting_grp">
            <input
              id="kitting_grp"
              name="kitting_grp"
              type="text"
              value={formData.kitting_grp}
              onChange={handleChange}
              disabled={formData.mixed_allow !== true}
              placeholder={
                formData.mixed_allow === true
                  ? "키팅 그룹 입력"
                  : ""
              }
              className={`h-[50px] w-[300px] rounded-[10px] bg-[#EBEDF1] px-[15px] text-center text-[24px] font-normal outline-none ${
                formData.mixed_allow === true
                  ? "cursor-text"
                  : "cursor-not-allowed"
              }`}
            />
          </FormRow>

          <FormRow label="사용 여부" htmlFor="use_yn">
            <YnSelect
              name="use_yn"
              value={formData.use_yn}
              onChange={handleChange}
            />
          </FormRow>
        </div>

        {/* 하단 버튼 */}
        <div className="flex w-[520px] justify-center gap-[30px]">
          <button
            type="button"
            onClick={onClose}
            className="flex h-[70px] w-[245px] items-center justify-center rounded-[10px] bg-[#8F949E] text-[32px] font-extrabold text-white"
          >
            {isCreateMode ? "취소" : "변경 취소"}
          </button>

          <button
            type="button"
            onClick={handleSubmit}
            className="flex h-[70px] w-[245px] items-center justify-center rounded-[10px] bg-[#243659] text-[32px] font-extrabold text-white"
          >
            {isCreateMode ? "등록" : "변경 사항 저장"}
          </button>
        </div>
      </div>
    </div>
  );
}

// 입력 항목 공통 행
function FormRow({ label, htmlFor, children }) {
  return (
    <div className="flex h-[50px] w-[480px] items-center justify-between">
      <label
        htmlFor={htmlFor}
        className="flex h-[30px] w-[150px] items-center text-[24px] font-normal"
      >
        {label}
      </label>

      {children}
    </div>
  );
}

// Y/N 선택박스
function YnSelect({ name, value, onChange }) {
  const selectValue =
    value === true ? "true" : value === false ? "false" : "";

  return (
    <div className="relative h-[50px] w-[300px]">
      <select
        id={name}
        name={name}
        value={selectValue}
        onChange={onChange}
        className="h-[50px] w-full cursor-pointer appearance-none rounded-[10px] bg-[#EBEDF1] pl-[45px] pr-[55px] text-center text-[24px] font-normal outline-none"
      >
        <option value="">선택</option>
        <option value="true">Y</option>
        <option value="false">N</option>
      </select>

      <img
        src={arrow_down_icon}
        alt=""
        aria-hidden="true"
        className="pointer-events-none absolute right-[20px] top-1/2 h-[12.46px] w-[21.2px] -translate-y-1/2"
      />
    </div>
  );
}

export default MaterialDetailModal;