import SensorStatus from "./sensor-status";

// 공통 페이지 헤더
function Header({ category, title, parentTitle }) {
  return (
    <div className="flex w-full items-end justify-between">
      {/* 페이지 제목 및 경로 */}
      <div className="flex items-end gap-[30px]">
        {/* 페이지 제목 */}
        <div className="flex h-[60px] min-w-[137px] items-center">
          <span className="whitespace-nowrap text-[48px] font-extrabold leading-none text-[#243659]">
            {title}
          </span>
        </div>

        {/* 현재 메뉴 경로 */}
        <div className="flex h-[46px] w-[724px] items-center">
          <span className="whitespace-nowrap text-[24px] font-semibold leading-none text-[#747983]">
            {category}
            {parentTitle && ` > ${parentTitle}`}
            {title && ` > ${title}`}
          </span>
        </div>
      </div>

      {/* 센서 연결 상태 */}
      <div className="flex h-[100px] w-[400px] gap-[10px] px-[10px]">
        <SensorStatus />
      </div>
    </div>
  );
}

export default Header;