import { useCallback, useEffect, useMemo, useState } from "react";
import search_icon from "../../assets/icon/search_icon.svg";
import Header from "../../components/layout/header";
import MaterialDetailModal from "../../components/modal/material-detail-modal";

// Boolean 값을 Y/N으로 표시
const formatYn = (value) => {
  if (value === null || value === undefined) {
    return "-";
  }

  return value ? "Y" : "N";
};

// 날짜 표시 형식 변환
const formatDate = (value) => {
  if (!value) {
    return "-";
  }

  return String(value).replace("T", " ").slice(0, 19);
};

function MaterialMaster() {
  // API Base URL 상태 관리
  const [baseUrl, setBaseUrl] = useState("");

  const [materialData, setMaterialData] = useState([]);
  const [searchInput, setSearchInput] = useState("");
  const [selectedMaterial, setSelectedMaterial] = useState(null);
  const [modalMode, setModalMode] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedMaterialIds, setSelectedMaterialIds] = useState([]);

  /*
   * 1. 컴포넌트 마운트 시 public/config.json 로드
   */
  useEffect(() => {
    const loadConfig = async () => {
      try {
        if (window.APP_CONFIG?.apiBaseUrl) {
          setBaseUrl(window.APP_CONFIG.apiBaseUrl);
          return;
        }

        const response = await fetch("/config.json");
        if (!response.ok) {
          throw new Error("config.json 로드 실패");
        }
        const config = await response.json();
        if (config?.apiBaseUrl) {
          setBaseUrl(config.apiBaseUrl);
        } else {
          console.error("config.json에 apiBaseUrl이 정의되어 있지 않습니다.");
        }
      } catch (error) {
        console.error("환경 설정 파일 로드 실패:", error);
      }
    };

    loadConfig();
  }, []);

  // 자재 목록 조회
  const fetchMaterialData = useCallback(async (apiBase, keyword = "") => {
    if (!apiBase) return;

    try {
      setIsLoading(true);

      const query = `?keyword=${encodeURIComponent(keyword ?? "")}`;

      const response = await fetch(`${apiBase}/get/items/master${query}`, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(
          result.msg ?? `자재 목록 조회 실패: ${response.status}`,
        );
      }

      if (!result.success) {
        throw new Error(result.msg ?? "자재 목록을 불러오지 못했습니다.");
      }

      setMaterialData(Array.isArray(result.data) ? result.data : []);
    } catch (error) {
      console.error("자재 목록 조회 오류:", error);
      setMaterialData([]);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // baseUrl 확보 시 최초 목록 조회
  useEffect(() => {
    if (baseUrl) {
      fetchMaterialData(baseUrl);
    }
  }, [baseUrl, fetchMaterialData]);

  // 자재코드, 자재명 검색 + 최종 수정일 오름차순 정렬
  const filteredData = useMemo(() => {
    return [...materialData].sort((a, b) => {
      const dateA = new Date(a.updated_date ?? a.created_date).getTime();
      const dateB = new Date(b.updated_date ?? b.created_date).getTime();

      return dateA - dateB;
    });
  }, [materialData]);

  // 검색 버튼 클릭
  const handleSearch = () => {
    setSelectedMaterialIds([]);
    fetchMaterialData(baseUrl, searchInput);
  };

  // 신규등록 모달 열기
  const handleAddMaterial = () => {
    setSelectedMaterial(null);
    setModalMode("create");
  };

  // 자재 상세 조회
  const handleShowMaterialDetail = async (itemSeq) => {
    if (itemSeq === null || itemSeq === undefined) {
      alert("자재 번호가 없습니다.");
      return;
    }

    if (!baseUrl) return;

    try {
      setIsLoading(true);

      const response = await fetch(
        `${baseUrl}/get/item/master?item_seq=${itemSeq}`,
        {
          method: "GET",
          headers: {
            Accept: "application/json",
          },
        },
      );

      const result = await response.json();

      if (!response.ok) {
        throw new Error(
          result.msg || `자재 상세 조회 실패: ${response.status}`,
        );
      }

      if (!result.success) {
        throw new Error(
          result.msg || "자재 상세 정보를 불러오지 못했습니다.",
        );
      }

      if (!result.data) {
        throw new Error("자재 상세 데이터가 없습니다.");
      }

      const detailData = Array.isArray(result.data)
        ? result.data[0]
        : result.data;

      if (!detailData) {
        throw new Error("자재 상세 데이터가 없습니다.");
      }

      setSelectedMaterial(detailData);
      setModalMode("edit");
    } catch (error) {
      console.error("자재 상세 조회 오류:", error);

      alert(
        error instanceof Error
          ? error.message
          : "자재 상세 조회 중 오류가 발생했습니다.",
      );
    } finally {
      setIsLoading(false);
    }
  };

  // 자재 선택
  const handleSelectMaterial = (seq) => {
    setSelectedMaterialIds((currentIds) => {
      if (currentIds.includes(seq)) {
        return currentIds.filter((id) => id !== seq);
      }

      return [...currentIds, seq];
    });
  };

  // 모달 닫기
  const handleCloseModal = () => {
    setSelectedMaterial(null);
    setModalMode(null);
  };

  // 자재 등록
  const handleSave = async (formData) => {
    if (!baseUrl) return;

    try {
      const requestBody = {
        item_code: formData.item_code.trim(),
        item_name: formData.item_name.trim(),
        uom: formData.uom.trim(),
        catch_weight_yn: true,
        washing_yn: formData.washing_yn,
        mixed_allow: formData.mixed_allow,
        kitting_grp:
          formData.mixed_allow === true
            ? formData.kitting_grp.trim() || null
            : null,
      };

      const response = await fetch(`${baseUrl}/insert/item/master`, {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.msg || `자재 등록 실패: ${response.status}`);
      }

      if (!result.success) {
        throw new Error(result.msg || "자재 등록에 실패했습니다.");
      }

      alert(result.msg || "자재가 등록되었습니다.");

      handleCloseModal();
      await fetchMaterialData(baseUrl);
    } catch (error) {
      console.error("자재 등록 오류:", error);

      alert(
        error instanceof Error
          ? error.message
          : "자재 등록 중 오류가 발생했습니다.",
      );
    }
  };

  // 자재 수정
  const handleUpdate = async (formData) => {
    if (formData.seq === null || formData.seq === undefined) {
      alert("수정할 자재 번호가 없습니다.");
      return;
    }

    if (!baseUrl) return;

    try {
      const requestBody = {
        seq: formData.seq,
        item_name: formData.item_name.trim(),
        uom: formData.uom.trim(),
        catch_weight_yn: true,
        washing_yn: formData.washing_yn,
        mixed_allow: formData.mixed_allow,
        kitting_grp:
          formData.mixed_allow === true
            ? formData.kitting_grp.trim() || null
            : null,
        use_yn: formData.use_yn,
      };

      const response = await fetch(`${baseUrl}/update/item/master`, {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.msg || `자재 수정 실패: ${response.status}`);
      }

      if (!result.success) {
        throw new Error(result.msg || "자재 수정에 실패했습니다.");
      }

      alert(result.msg || "자재 정보가 수정되었습니다.");

      handleCloseModal();
      await fetchMaterialData(baseUrl);
    } catch (error) {
      console.error("자재 수정 오류:", error);

      alert(
        error instanceof Error
          ? error.message
          : "자재 수정 중 오류가 발생했습니다.",
      );
    }
  };


  return (
    <div className="flex h-[1080px] w-[1560px] flex-col gap-[30px] p-[30px]">
      {/* 헤더 영역 */}
      <div className="flex h-[100px] w-[1500px] shrink-0 items-end gap-[30px]">
        <Header category="시스템" title="자재 마스터 관리" />
      </div>

      {/* 하단 콘텐츠 영역 */}
      <div className="flex h-[890px] w-[1500px] flex-col gap-[30px] pt-[30px]">
        {/* 검색 및 버튼 영역 */}
        <div className="flex h-[70px] w-full items-center gap-[20px]">
          {/* 검색창 */}
          <div className="flex h-[70px] w-[1330px] items-center gap-[10px] rounded-[10px] bg-[#EBEDF1] px-[20px]">
            <input
              id="material-search"
              name="material-search"
              type="text"
              value={searchInput}
              onChange={(event) => setSearchInput(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") {
                  handleSearch();
                }
              }}
              placeholder="자재코드, 자재명 검색"
              className="h-[40px] min-w-0 flex-1 bg-transparent text-[24px] font-medium text-[#202020] outline-none placeholder:text-[#A8ADB5]"
            />

            <button
              type="button"
              onClick={handleSearch}
              className="flex h-[43.43px] w-[42.5px] shrink-0 cursor-pointer items-center justify-center"
            >
              <img
                src={search_icon}
                alt="검색"
                className="h-[38px] w-[37px] object-contain"
              />
            </button>
          </div>

          {/* 신규등록 */}
          <button
            type="button"
            onClick={handleAddMaterial}
            className="flex h-[70px] w-[150px] shrink-0 items-center justify-center rounded-[10px] bg-[#243659] px-[20px]"
          >
            <span className="text-[24px] font-semibold text-white">
              신규등록
            </span>
          </button>
        </div>

        <div className="h-[2px] w-full shrink-0 bg-[#EEEEEE]" />

        {/* 자재 리스트 */}
        <div className="flex h-[730px] w-[1500px] gap-[30px]">
          <div className="flex h-[730px] w-full shrink-0 flex-col overflow-hidden rounded-[10px] border border-[#E8E8E8]">
            {/* 리스트 헤더 */}
            <div className="grid h-[60px] w-full shrink-0 grid-cols-[100px_210px_260px_120px_150px_170px_180px_190px_120px] items-center bg-[#243659]">
              <div className="text-center text-[22px] font-bold text-white">
                선택
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                자재코드
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                자재명
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                단위
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                세척 여부
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                혼적 허용
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                키팅 그룹
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                최종 수정일
              </div>

              <div className="text-center text-[22px] font-bold text-white">
                사용 여부
              </div>
            </div>

            {/* 리스트 데이터 */}
            <div className="custom-scrollbar min-h-0 flex-1 overflow-y-auto">
              {isLoading ? (
                <div className="flex h-full items-center justify-center">
                  <span className="text-[32px] font-bold text-[#8F949E]">
                    자재 목록을 불러오는 중입니다.
                  </span>
                </div>
              ) : filteredData.length === 0 ? (
                <div className="flex h-full items-center justify-center">
                  <span className="text-[36px] font-bold text-[#8F949E]">
                    목록 없음
                  </span>
                </div>
              ) : (
                filteredData.map((item, index) => (
                  <button
                    key={item.seq}
                    type="button"
                    onClick={() => handleShowMaterialDetail(item.seq)}
                    disabled={isLoading}
                    className="grid h-[60px] w-full shrink-0 cursor-pointer grid-cols-[100px_210px_260px_120px_150px_170px_180px_190px_120px] items-center overflow-hidden bg-white text-left hover:bg-[#F4F6F9]"
                  >
                    <div className="truncate px-[10px] text-center text-[24px] text-black">
                      <input
                        type="checkbox"
                        checked={selectedMaterialIds.includes(item.seq)}
                        onChange={() => handleSelectMaterial(item.seq)}
                        onClick={(event) => event.stopPropagation()}
                        className="h-[20px] w-[20px] cursor-pointer focus:ring-0"
                        aria-label={`${item.item_code || "자재"} 선택`}
                      />
                    </div>

                    <div className="truncate px-[10px] text-center text-[24px] text-black">
                      {item.item_code || "-"}
                    </div>

                    <div
                      title={item.item_name || ""}
                      className="truncate px-[10px] text-center text-[24px] text-black"
                    >
                      {item.item_name || "-"}
                    </div>

                    <div className="truncate px-[10px] text-center text-[24px] text-black">
                      {item.uom || "-"}
                    </div>

                    <div className="truncate px-[10px] text-center text-[24px] text-black">
                      {formatYn(item.washing_yn)}
                    </div>

                    <div className="truncate px-[10px] text-center text-[24px] text-black">
                      {formatYn(item.mixed_allow)}
                    </div>

                    <div className="truncate px-[10px] text-center text-[24px] text-black">
                      {item.kitting_grp || "-"}
                    </div>

                    <div className="truncate px-[10px] text-center text-[22px] text-black">
                      {formatDate(item.updated_date || item.created_date)}
                    </div>

                    <div className="truncate px-[10px] text-center text-[24px] text-black">
                      {formatYn(item.use_yn)}
                    </div>
                  </button>
                ))
              )}
            </div>
          </div>
        </div>
      </div>

      {/* 신규등록 및 수정 모달 */}
      {modalMode && (
        <MaterialDetailModal
          mode={modalMode}
          material={selectedMaterial}
          onClose={handleCloseModal}
          onSave={handleSave}
          onUpdate={handleUpdate}
        />
      )}
    </div>
  );
}

export default MaterialMaster;
