import { useState } from "react";
import x_icon from "../../assets/icon/x_Icon.svg";


function LpnModal({ data, onClose }) {
  const [selectedRowId, setSelectedRowId] = useState(null);
  const detailList = data?.items ?? [];

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/20 backdrop-blur-[3px]">
      <div className="relative flex min-h-[565px] w-[1200px] flex-col items-center gap-[30px] rounded-[20px] bg-white p-[30px]">
        {/* 모달 헤더 */}
        <div className="relative h-[50px] w-full">
          <h2 className="absolute inset-0 flex items-center justify-center whitespace-nowrap text-[40px] font-extrabold">
            {data?.lpn_code ?? "-"}
          </h2>

          <button
            type="button"
            onClick={onClose}
            aria-label="모달 닫기"
            className="absolute right-0 top-1/2 flex h-[37px] w-[37px] -translate-y-1/2 items-center justify-center"
          >
            <img
              src={x_icon}
              alt=""
              aria-hidden="true"
              className="h-[18.5px] w-[18.5px]"
            />
          </button>
        </div>

        {/* 상세 정보 영역 */}
        <div className="flex min-h-[475px] w-full flex-col gap-[10px] ">
          <div className="flex h-[25px] w-full justify-end text-[20px] text-[#9A9FA8]">
            발행 일자 : {data?.txn_date?.replace("T", " ").slice(0, 19) ?? "-"}
          </div>

          <div className="flex h-[390px] w-full flex-col overflow-hidden rounded-[20px] gap-[10px] border border-[#DFDFDF] px-[10px] py-[10px]">
            <div className="flex w-full h-[50px] rounded-[20px] items-center border border-[#DFDFDF]">
              <div className="flex w-full items-center">
                <span className="rounded-l-[20px] h-[50px] w-[150px] bg-[#243659] flex justify-center items-center text-[22px] font-bold text-white">
                  호기
                </span>
                <span className="flex h-[50px] w-full justify-center items-center text-[22px] font-normal text-black">
                  {data?.engine_no}
                </span>
              </div>
              <div className="flex w-full items-center">
                <span className="h-[50px] w-[150px] bg-[#243659] flex justify-center items-center text-[22px] font-bold text-white">
                  공정
                </span>
                <span className="flex h-[50px] w-full justify-center items-center text-[22px] font-normal text-black">
                  {data?.proc_code}
                </span>
              </div>
              <div className="flex w-full items-center ">
                <span className="h-[50px] w-[150px] bg-[#243659] flex justify-center items-center text-[22px] font-bold text-white">
                  서열
                </span>
                <span className="flex h-[50px] w-full justify-center items-center text-[22px] font-normal text-black">
                  {data?.mes_seq_no}
                </span>
              </div>
            </div>
            {/* 헤더 */}
            <div className="flex-1 rounded-[20px] border border-[#DFDFDF] overflow-hidden">
              <div className="grid h-[60px] grid-cols-[100px_220px_220px_220px_100px_220px] bg-[#243659]">
                <div className="flex items-center justify-center text-[22px] font-bold text-white">
                  순번
                </div>

                <div className="flex items-center justify-center text-[22px] font-bold text-white">
                  LPN
                </div>

                <div className="flex items-center justify-center text-[20px] font-bold text-white">
                  자재 코드
                </div>

                <div className="flex items-center justify-center text-[22px] font-bold text-white">
                  자재명
                </div>

                <div className="flex items-center justify-center text-[22px] font-bold text-white">
                  수량
                </div>

                <div className="flex items-center justify-center text-[22px] font-bold text-white">
                  입고일
                </div>
              </div>

              {/* 데이터 */}
              <div className="scrollbar-hidden flex-1 overflow-y-auto max-h-[330px]">
                {detailList.map((item, index) => (
                  <div
                    key={item.txn_seq}
                    className={`grid h-[65px] grid-cols-[100px_220px_220px_220px_100px_220px] border-b border-[#DFDFDF]
                      ${
                        selectedRowId === item.txn_seq
                          ? "bg-[#EBEDF1]"
                          : "bg-white hover:bg-[#EBEDF1]"
                      }`}
                    onClick={() => setSelectedRowId(item.txn_seq)}
                  >
                    <div className="flex items-center justify-center text-[22px]">
                      {index + 1}
                    </div>

                    <div className="flex items-center justify-center text-[22px]">
                      {item.pre_lpn_code}
                    </div>

                    <div className="flex items-center justify-center text-[22px]">
                      {item.item_code}
                    </div>

                    <div className="flex items-center justify-center text-[22px]">
                      {item.item_name}
                    </div>

                    <div className="flex items-center justify-center text-[22px]">
                      {item.qty}
                    </div>
                    <div className="flex items-center justify-center text-[22px]">
                      {data?.txn_date?.replace("T", " ").slice(0, 19)}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default LpnModal;
