import { useCallback, useEffect, useMemo, useState } from "react";

import Header from "../../components/layout/header";
import RackSection from "../../components/rack/rack-section";
import RackSectionDetail from "../../components/management/rack-section-detail";

function RackView() {
  // API Base URL 상태 관리
  const [baseUrl, setBaseUrl] = useState("");

  // 전체 랙 목록
  const [rackList, setRackList] = useState([]);

  // 현재 선택한 구역 이름
  const [selectedZone, setSelectedZone] = useState("");

  // 현재 선택한 랙 seq
  const [selectedRackSeq, setSelectedRackSeq] = useState("");

  // 현재 선택한 셀의 상세정보
  const [selectedCell, setSelectedCell] = useState(null);

  // 상세정보를 조회 중인 셀 seq
  const [loadingCellSeq, setLoadingCellSeq] = useState(null);

  // 선택한 랙의 격자 데이터
  const [gridRack, setGridRack] = useState(null);

  // 격자 조회 로딩 상태
  const [gridLoading, setGridLoading] = useState(false);

  /*
   * 1. 컴포넌트 마운트 시 public/config.json 로드
   */
  useEffect(() => {
    const loadConfig = async () => {
      try {
        const response = await fetch("/config.json");
        if (!response.ok) {
          throw new Error("config.json 로드 실패");
        }
        const config = await response.json();
        if (config?.apiBaseUrl) {
          setBaseUrl(config.apiBaseUrl);
        } else {
          console.error("config.json에 apiBaseUrl이 정의되어 있지 않습니다.");
        }
      } catch (error) {
        console.error("환경 설정 파일 로드 실패:", error);
      }
    };

    loadConfig();
  }, []);

  /*
   * 전체 랙 목록에서 중복되지 않는 구역 목록 생성
   */
  const zoneOptions = useMemo(() => {
    const zoneMap = new Map();

    rackList.forEach((rack) => {
      const zoneSeq = rack.zone_seq;
      const zoneName = rack.zone_name;

      if (zoneSeq === null || zoneSeq === undefined || !zoneName) {
        return;
      }

      zoneMap.set(String(zoneSeq), {
        seq: zoneSeq,
        zone_name: zoneName,
      });
    });

    return [...zoneMap.values()].sort((a, b) => Number(a.seq) - Number(b.seq));
  }, [rackList]);

  /*
   * 현재 선택된 구역 정보
   */
  const selectedZoneInfo = useMemo(() => {
    return zoneOptions.find((zone) => zone.zone_name === selectedZone);
  }, [zoneOptions, selectedZone]);

  /*
   * 현재 선택한 구역에 소속된 랙 목록
   */
  const rackOptions = useMemo(() => {
    if (!selectedZoneInfo?.seq) {
      return [];
    }

    return rackList.filter(
      (rack) => String(rack.zone_seq) === String(selectedZoneInfo.seq),
    );
  }, [rackList, selectedZoneInfo?.seq]);

  /*
   * 전체 랙 목록 조회
   */
  const fetchRackList = useCallback(async (apiBase) => {
    if (!apiBase) return;

    try {
      const response = await fetch(`${apiBase}/get/all/rack/master`, {
        method: "GET",
        headers: { Accept: "application/json" },
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.detail ??
            result?.msg ??
            `랙 목록 조회 실패: ${response.status}`,
        );
      }

      const list = Array.isArray(result?.data)
        ? result.data
        : Array.isArray(result)
          ? result
          : [];

      const activeRackList = list.filter(
        (rack) =>
          rack.enable_yn !== false &&
          rack.enable_yn !== 0 &&
          rack.enable_yn !== "N",
      );

      setRackList(activeRackList);
    } catch (error) {
      console.error("랙 목록 조회 실패:", error);

      setRackList([]);
      setSelectedZone("");
      setSelectedRackSeq("");
      setGridRack(null);
      setSelectedCell(null);

      alert(error.message ?? "랙 목록 조회 중 오류가 발생했습니다.");
    }
  }, []);

  /*
   * baseUrl이 확보된 후 랙 목록 조회 실행
   */
  useEffect(() => {
    if (baseUrl) {
      fetchRackList(baseUrl);
    }
  }, [baseUrl, fetchRackList]);

  // 구역 기본값 자동 선택
  useEffect(() => {
    if (zoneOptions.length === 0) {
      setSelectedZone("");
      setSelectedRackSeq("");
      setGridRack(null);
      setSelectedCell(null);
      return;
    }

    const selectedZoneExists = zoneOptions.some(
      (zone) => zone.zone_name === selectedZone,
    );

    if (!selectedZoneExists) {
      setSelectedZone(zoneOptions[0].zone_name);

      setSelectedRackSeq("");
      setGridRack(null);
      setSelectedCell(null);
    }
  }, [zoneOptions, selectedZone]);

  // 랙 기본값 자동 선택
  useEffect(() => {
    if (rackOptions.length === 0) {
      setSelectedRackSeq("");
      setGridRack(null);
      setSelectedCell(null);
      return;
    }

    const selectedRackExists = rackOptions.some(
      (rack) => String(rack.seq) === String(selectedRackSeq),
    );

    if (!selectedRackExists) {
      setSelectedRackSeq(String(rackOptions[0].seq));

      setGridRack(null);
      setSelectedCell(null);
    }
  }, [rackOptions, selectedRackSeq]);

  /*
   * 랙 격자 조회
   */
  const fetchZoneGrid = useCallback(
    async (zoneSeq, rackSeq) => {
      if (!baseUrl || !zoneSeq || !rackSeq) {
        setGridRack(null);
        setSelectedCell(null);
        return;
      }

      try {
        setGridLoading(true);
        setGridRack(null);
        setSelectedCell(null);

        const requestUrl =
          `${baseUrl}/get/zone/grid/${zoneSeq}` +
          `?rack_seq=${encodeURIComponent(rackSeq)}`;

        const response = await fetch(requestUrl, {
          method: "GET",
          headers: { Accept: "application/json" },
        });

        const result = await response.json().catch(() => null);

        if (!response.ok) {
          throw new Error(
            result?.detail ??
              result?.msg ??
              `랙 격자 조회 실패: ${response.status}`,
          );
        }

        const responseData = Array.isArray(result?.data) ? result.data : [];

        const rackGrid =
          responseData.find(
            (rack) => String(rack.rack_seq) === String(rackSeq),
          ) ??
          responseData[0] ??
          null;

        if (!rackGrid) {
          setGridRack(null);
          return;
        }

        const normalizedCells = Array.isArray(rackGrid.cells)
          ? rackGrid.cells.map((cell, index) => ({
              ...cell,
              index,
              id: cell.location_seq ?? `${rackGrid.rack_seq}-${index}`,
              seq: cell.location_seq ?? null,
              locationSeq: cell.location_seq ?? null,
              locationCode: cell.location_code ?? "-",
              cellCode: cell.location_code ?? "-",
              rack_seq: rackGrid.rack_seq,
              rackCode: rackGrid.rack_code,
              rackName: rackGrid.rack_name,
              available: cell.enable_yn !== false,
              lpnCount: Number(cell.lpn_cnt ?? 0),
              itemKindCount: Number(cell.item_kind_cnt ?? 0),
              totalQty: Number(cell.total_qty ?? 0),
            }))
          : [];

        setGridRack({
          ...rackGrid,
          id: rackGrid.rack_seq,
          seq: rackGrid.rack_seq,
          rows: Number(rackGrid.rows ?? 0),
          cols: Number(rackGrid.cols ?? 6),
          total_cell: Number(
            rackGrid.total_cell ?? normalizedCells.length,
          ),
          used_cell: Number(rackGrid.used_cell ?? 0),
          cells: normalizedCells,
        });
      } catch (error) {
        console.error("랙 격자 조회 실패:", error);

        setGridRack(null);
        setSelectedCell(null);

        alert(error.message ?? "랙 격자 조회 중 오류가 발생했습니다.");
      } finally {
        setGridLoading(false);
      }
    },
    [baseUrl],
  );

  /*
   * 선택된 구역 또는 랙이 변경되면 격자 조회
   */
  useEffect(() => {
    if (!selectedZoneInfo?.seq || !selectedRackSeq) {
      setGridRack(null);
      setSelectedCell(null);
      return;
    }

    fetchZoneGrid(selectedZoneInfo.seq, selectedRackSeq);
  }, [selectedZoneInfo?.seq, selectedRackSeq, fetchZoneGrid]);

  // 구역 선택 변경
  const handleZoneChange = (event) => {
    setSelectedZone(event.target.value);
    setSelectedRackSeq("");
    setGridRack(null);
    setSelectedCell(null);
  };

  // 랙 선택 변경
  const handleRackChange = (event) => {
    setSelectedRackSeq(event.target.value);

    setGridRack(null);
    setSelectedCell(null);
  };

  /*
   * 셀 클릭 시 상세정보 조회
   */
  const handleCellClick = async (rack, cell) => {
    const locationSeq = Number(
      cell.location_seq ?? cell.locationSeq ?? cell.seq,
    );

    if (!Number.isInteger(locationSeq) || locationSeq < 1) {
      console.error("올바르지 않은 location_seq:", cell);
      return;
    }

    const commonCellData = {
      ...cell,
      id: locationSeq,
      seq: locationSeq,
      location_seq: locationSeq,
      locationSeq,
      location_code: cell.location_code ?? cell.locationCode ?? "-",
      locationCode: cell.location_code ?? cell.locationCode ?? "-",
      cellCode: cell.location_code ?? cell.locationCode ?? "-",
      rack_seq: rack.rack_seq ?? rack.seq,
      rackSeq: rack.rack_seq ?? rack.seq,
      rack_code: rack.rack_code ?? rack.rackCode ?? "-",
      rackCode: rack.rack_code ?? rack.rackCode ?? "-",
      rack_name: rack.rack_name ?? rack.rackName ?? "-",
      rackName: rack.rack_name ?? rack.rackName ?? "-",
      row_no: cell.row_no ?? cell.rowNo,
      col_no: cell.col_no ?? cell.colNo,
      lpn_cnt: Number(cell.lpn_cnt ?? cell.lpnCount ?? 0),
      lpnCount: Number(cell.lpn_cnt ?? cell.lpnCount ?? 0),
      item_kind_cnt: Number(cell.item_kind_cnt ?? cell.itemKindCount ?? 0),
      itemKindCount: Number(cell.item_kind_cnt ?? cell.itemKindCount ?? 0),
      total_qty: Number(cell.total_qty ?? cell.totalQty ?? 0),
      totalQty: Number(cell.total_qty ?? cell.totalQty ?? 0),
    };

    // 클릭 즉시 로딩 표시
    setSelectedCell({
      ...commonCellData,
      lpnList: [],
      detailLoading: true,
      detailError: null,
    });

    try {
      setLoadingCellSeq(locationSeq);

      const response = await fetch(`${baseUrl}/get/cell/${locationSeq}`, {
        method: "GET",
        headers: { Accept: "application/json" },
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.detail ??
            result?.msg ??
            `셀 상세 조회 실패: ${response.status}`,
        );
      }

      const detail = result?.data ?? {};

      const lpnList = Array.isArray(detail.lpns)
        ? detail.lpns.map((lpn) => ({
            ...lpn,
            lpn_master_seq: lpn.lpn_master_seq ?? null,
            lpn_code: lpn.lpn_code ?? "-",
            lpn_type: lpn.lpn_type ?? "",
            process_status: lpn.process_status ?? "",
            split_yn: Boolean(lpn.split_yn),
            receipt_date: lpn.receipt_date ?? null,
            order_no: lpn.order_no ?? null,
            engine_no: lpn.engine_no ?? null,
            proc_code: lpn.proc_code ?? null,
            total_qty: Number(lpn.total_qty ?? 0),
            items: Array.isArray(lpn.items)
              ? lpn.items.map((item) => ({
                  ...item,
                  lpn_detail_seq: item.lpn_detail_seq,
                  item_seq: item.item_seq,
                  item_code: item.item_code ?? "-",
                  item_name: item.item_name ?? "-",
                  uom: item.uom ?? "",
                  washing_yn: Boolean(item.washing_yn),
                  init_qty: Number(item.init_qty ?? 0),
                  current_qty: Number(item.current_qty ?? 0),
                }))
              : [],
          }))
        : [];

      // 상세 조회 성공 시 단일 업데이트
      setSelectedCell({
        ...commonCellData,
        location_seq: detail.location_seq ?? commonCellData.location_seq,
        location_code: detail.location_code ?? commonCellData.location_code,
        row_no: detail.row_no ?? commonCellData.row_no,
        col_no: detail.col_no ?? commonCellData.col_no,
        enable_yn: detail.enable_yn ?? commonCellData.enable_yn,
        rack_seq: detail.rack_seq ?? commonCellData.rack_seq,
        rack_code: detail.rack_code ?? commonCellData.rack_code,
        rack_name: detail.rack_name ?? commonCellData.rack_name,
        zone_seq: detail.zone_seq,
        zone_code: detail.zone_code,
        zone_name: detail.zone_name,
        zone_type: detail.zone_type,
        lpn_cnt: Number(detail.lpn_cnt ?? commonCellData.lpn_cnt),
        total_qty: Number(detail.total_qty ?? commonCellData.total_qty),
        lpnList,
        detailLoading: false,
        detailError: null,
      });
    } catch (error) {
      console.error("셀 상세 조회 실패:", error);

      setSelectedCell({
        ...commonCellData,
        lpnList: [],
        detailLoading: false,
        detailError: error.message ?? "셀 상세 조회에 실패했습니다.",
      });
    } finally {
      setLoadingCellSeq(null);
    }
  };

  return (
    <div className="flex h-full w-full items-center justify-center">
      <div className="flex h-[1080px] w-[1560px] flex-col gap-[30px] p-[30px]">
        {/* 헤더 */}
        <div className="flex h-[100px] w-[1500px] shrink-0 items-end gap-[30px]">
          <Header category="조회" title="랙 적재 현황 조회" />
        </div>

        <div className="flex h-[890px] w-[1500px] flex-col gap-[30px]">
          {/* 조회 조건 */}
          <div className="flex h-[55px] w-full shrink-0 justify-between">
            {/* 랙 위치 */}
            <div className="flex h-[55px] w-[700px] shrink-0 items-center gap-[30px]">
              <label
                htmlFor="rack-zone"
                className="w-[150px] shrink-0 text-[32px] font-bold leading-none text-black"
              >
                랙 위치
              </label>

              <div className="flex h-[55px] flex-1 items-center rounded-[10px] bg-[#EBEDF1] px-[20px] py-[10px]">
                <select
                  id="rack-zone"
                  name="rack-zone"
                  value={selectedZone}
                  onChange={handleZoneChange}
                  disabled={zoneOptions.length === 0}
                  className="h-full w-full cursor-pointer bg-[#EBEDF1] text-center text-[28px] font-semibold text-black outline-none disabled:cursor-not-allowed"
                >
                  {zoneOptions.map((zone) => (
                    <option key={zone.seq} value={zone.zone_name}>
                      {zone.zone_name}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* 랙 번호 */}
            <div className="flex h-[55px] w-[700px] shrink-0 items-center gap-[30px]">
              <label
                htmlFor="rack-number"
                className="w-[150px] shrink-0 text-[32px] font-bold leading-none text-black"
              >
                랙 번호
              </label>

              <div className="flex h-[55px] flex-1 items-center rounded-[10px] bg-[#EBEDF1] px-[20px]">
                <select
                  id="rack-number"
                  name="rack-number"
                  value={selectedRackSeq}
                  onChange={handleRackChange}
                  disabled={rackOptions.length === 0}
                  className="h-full w-full cursor-pointer bg-[#EBEDF1] text-center text-[28px] font-semibold text-black outline-none disabled:cursor-not-allowed"
                >
                  {rackOptions.map((rack) => (
                    <option key={rack.seq} value={rack.seq}>
                      {rack.rack_code}
                      {rack.rack_name ? ` - ${rack.rack_name}` : ""}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          <div className="h-[2px] w-full shrink-0 bg-[#EEEEEE]" />

          {/* 랙 및 상세정보 */}
          <div className="flex h-[745px] w-[1500px] gap-[30px]">
            {/* 랙 격자 */}
            <div className="hide-scrollbar flex h-full w-[835px] flex-col gap-[20px] overflow-y-auto overflow-x-hidden">
              {gridLoading ? (
                <div className="flex h-full w-full items-center justify-center rounded-[10px] border border-[#DBDBDB] bg-white">
                  <span className="text-[32px] font-bold text-[#747983]">
                    불러오는 중...
                  </span>
                </div>
              ) : gridRack ? (
                <RackSection
                  key={gridRack.rack_seq}
                  rackData={gridRack}
                  selectedCell={selectedCell}
                  loadingCellSeq={loadingCellSeq}
                  onCellClick={handleCellClick}
                />
              ) : (
                <div className="flex h-full w-full items-center justify-center rounded-[10px] border border-[#DBDBDB] bg-white">
                  <span className="text-[32px] font-bold text-[#747983]">
                    표시할 랙 정보가 없습니다.
                  </span>
                </div>
              )}
            </div>

            {/* 선택 위치 상세정보 */}
            <div className="flex h-full w-[635px] shrink-0 flex-col">
              <div className="h-full w-full overflow-hidden rounded-[10px] border border-[#DBDBDB] bg-[#EBEDF1] px-[50px] pb-[30px] pt-[50px]">
                <RackSectionDetail selectedCell={selectedCell} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default RackView;
